insert into public.confessions (id, user_id, content, is_anonymous, category, mood_tag, like_count, comment_count, moderation_status, created_at) values
  ('3faaa36b-5582-4e67-b8c3-2029e89b8803', (select id from public.profiles order by random() limit 1), 'Eşimle on yıllık evliyiz ve son zamanlarda her şey bir rutine binmişti; aynı saatte yatıyor, sırtımızı dönüp uyuyorduk. Geçen hafta bir cuma akşamı, çocukları annesine bıraktım, eve mum ışıkları dizdim, kırmızı bir elbise giydim ve onu kapıda öyle karşıladım. İçeri girdiğinde donup kaldı, yıllardır görmediği o bakışla baktı bana. O gece sabaha kadar konuştuk, güldük, ilk günlerimizdeki gibi birbirimize sarıldık. Meğer tutku kaybolmamış, sadece üstü tozlanmış. O geceden sonra evliliğimiz baştan doğdu. İtirafım: bazen alev sönmüyor, sadece birinin yeniden üflemesini bekliyor. Siz de eşinize bir sürpriz yapın, pişman olmayacaksınız.', true, 'Fantezi', 'Fantezi', 1316, 435, 'approved', now() - interval '27148 minutes'),
  ('4f3b5706-9f39-4cd0-9692-acc1d5d3f265', (select id from public.profiles order by random() limit 1), 'İş yerinde benden iki kat uzaklıkta oturan biri var; her sabah asansörde karşılaştığımızda kalbim deli gibi atıyor, kelimeler boğazımda düğümleniyor. Bana her gülümsediğinde tüm gün o gülüşü düşünüyorum, kahve molalarını sırf ona denk gelmek için ayarlıyorum. Aramızda hiçbir şey yaşanmadı, sadece bakışlar, yarım kalan cümleler, elimiz değdiğinde içimden geçen o elektrik. Bekarım, o da öyle ama ikimiz de adım atmaya korkuyoruz. Geçen gün asansörde gözlerimiz kilitlendi ve birkaç saniye hiç konuşamadık, nefesim kesildi. Bu gerilimi daha fazla taşıyamıyorum. Ona açılmalı mıyım, yoksa bu tatlı işkence böyle mi sürmeli?', true, 'Aşk', 'Aşk', 4447, 183, 'approved', now() - interval '14020 minutes'),
  ('19be4e9d-0b7c-49f6-850b-a7fe99b44216', (select id from public.profiles order by random() limit 1), 'Eşim utangaç biridir, hep kapalı kapılar ardında yaşadık. Ama doğum günümde beni şaşırttı; eve geldiğimde tüm evi gül yapraklarıyla donatmış, fonda yavaş bir şarkı, elinde iki kadeh vardı. Bana yaklaşıp kulağıma bu gece sadece ikimiz, telefon yok, dünya yok diye fısıldadı ve o an dizlerimin bağı çözüldü. Yıllardır onun bu kadar cesur, bu kadar tutkulu olabileceğini bilmiyordum. O gece yeni biriyle tanışmış gibi oldum, hâlbuki yıllardır aynı yataktaydık. Demek ki insanın içinde sakladığı bir ateş varmış, sadece güvenli hissedince ortaya çıkıyormuş. O geceyi ömrüm boyunca unutmayacağım. İtirafım: en büyük tutku, en sessiz insanların içinde saklıymış.', true, 'Fantezi', 'Fantezi', 2796, 812, 'approved', now() - interval '11407 minutes'),
  ('94707384-7762-4498-8cca-b1e59cf33c1b', (select id from public.profiles order by random() limit 1), 'Yıllardır içimde sakladığım bir fantezi vardı ama eşime söylemekten utanıyordum, ya tuhaf karşılarsa diye. Geçen ay bir gece, ışıkları kısık, cesaretimi toplayıp ona en gizli hayalimi anlattım. Beni dinlerken yüzünde önce şaşkınlık, sonra muzip bir gülümseme belirdi ve neden bunca yıl söylemedin dedi. Meğer onun da benzer hayalleri varmış, ikimiz de yıllardır aynı şeyi düşünüp birbirimizden saklamışız. O akşam bir oyun kurduk, gülmekten ve heyecandan yanaklarımız kızardı. İtirafım: en büyük yakınlık, en gizli arzularını paylaşabildiğin insanla oluyormuş. Çiftlere tavsiyem; konuşun, utanmayın, çünkü o utangaçlık aranızdaki en güzel anları çalıyor.', true, 'Fantezi', 'Fantezi', 86, 12, 'approved', now() - interval '32847 minutes'),
  ('0e8fb3f2-bf5e-4b7b-b402-bf7413cd2456', (select id from public.profiles order by random() limit 1), 'Spor salonunda her gün aynı saatte gelen biri var; antrenman yaparken farkında olmadan hep ona bakıyorum, o da bazen gözlerimi yakalayıp gülümsüyor. Aramızda sadece birkaç laf, bir su şişesi uzatması, bir alet paylaşımı oldu ama her temasında içimde bir şeyler kıpırdıyor. Dün ağırlık kaldırırken yanıma geldi, formumu düzeltmek için elini sırtıma koydu ve o an kalbim göğsümden fırlayacak sandım, terim bir anda soğudu. Numaramı istedi, ben de utangaç bir gülümsemeyle verdim. Bu akşam ilk mesajı bekliyorum, telefonu elimden bırakamıyorum. Bir bakışın, bir dokunuşun insanı bu kadar etkilemesi normal mi? İçimdeki bu heyecanı yıllardır hissetmemiştim.', true, 'Aşk', 'Aşk', 1247, 154, 'approved', now() - interval '32208 minutes'),
  ('2713f4d1-774d-4648-970e-c0c193be707b', (select id from public.profiles order by random() limit 1), 'Eşimle uzun bir aradan sonra ilk kez bir kaçamak tatile çıktık; deniz kenarında, kimsenin bizi tanımadığı bir kasaba. O akşam sahilde el ele yürürken, yıllar önceki o ilk randevumuzun heyecanını yeniden yaşadık. Otele döndüğümüzde balkon kapısı açıktı, dalga sesleri geliyordu, o beni belimden tutup kendine çekti ve uzun uzun öptü. Sanki yıllar geri sarmış, yeniden o ilk günkü âşıklar olmuştuk. Sabaha kadar uyumadık, sadece konuştuk, güldük, sarıldık. İtirafım: bazen tutkuyu yeniden bulmak için sadece rutinden, dört duvardan çıkmak, telefonları kapatmak yetiyormuş. O üç gün, evliliğimizin son beş yılından daha değerliydi.', true, 'Fantezi', 'Fantezi', 1285, 701, 'approved', now() - interval '30890 minutes'),
  ('aaeceeac-197c-4db9-8665-291b5e3cdadb', (select id from public.profiles order by random() limit 1), 'Komşum, eşi sürekli iş seyahatlerinde olan, son derece kibar ve yakışıklı bir adam. Apartman boşluğunda karşılaştığımızda nasılsınız demekle başlayan sohbetler giderek uzadı, kapı önünde dakikalarca konuşur olduk. Geçen gün asansörde aynı anda bindik ve dar alanda omzumuz değdiğinde ikimiz de bir an sustuk, havadaki gerilim elle tutulur gibiydi. İkimiz de evliyiz, hiçbir şey yaşanmadı ama o bakış, o yakınlık beni hem korkutuyor hem heyecanlandırıyor. Onu düşünmemek için kendimi zor tutuyorum. Bu sadece masum bir çekim mi, yoksa tehlikeli bir oyunun başlangıcı mı? Bu duyguyu söküp atmam gerektiğini biliyorum ama içimdeki o kıvılcım inatla yanıyor.', true, 'Aşk', 'Aşk', 488, 59, 'approved', now() - interval '5917 minutes'),
  ('17a374a8-c8ba-439a-8bb6-00f030f818c8', (select id from public.profiles order by random() limit 1), 'Eşim bana sürekli işten yorgun geliyorum diyordu, aramızdaki ateş iyice sönmüştü ve ben bunu dert ediyordum. Bir gün bir dergide okuduğum öneriyi denedim; ona gün içinde ufak, çapkın mesajlar atmaya başladım, bu akşam seni bekliyorum, sürprizim var gibi. Akşam eve geldiğinde gözlerindeki o merak ve heyecan görülmeye değerdi, yorgunluğu bir anda uçmuştu. O akşam ikimiz de gencecik âşıklar gibi kıkırdadık, oyunlar oynadık. Meğer tutku gün boyu beslenen bir ateşmiş, akşamı beklemek yetmiyormuş. İtirafım: bir evliliği canlı tutmak için bazen küçük bir mesaj, küçük bir gizli söz yetiyor. O günden beri her gün birbirimizi gün içinde ateşliyoruz ve evimiz yeniden bir balayı evine döndü.', true, 'Fantezi', 'Fantezi', 1186, 85, 'approved', now() - interval '24387 minutes'),
  ('e62c7f59-de67-4d12-ab91-0c4bca202190', (select id from public.profiles order by random() limit 1), 'Üniversiteden eski sevgilim, yıllar sonra bir iş toplantısında karşıma çıktı ve sanki zaman hiç geçmemiş gibi içimdeki o eski yangın bir anda tutuştu. İkimiz de başka hayatlar kurmuştuk ama gözlerimiz buluştuğunda, o eski tutkunun hâlâ orada olduğunu ikimiz de anladık. Toplantıdan sonra bir kahve içtik, eski günleri konuştuk ve masanın altında bir an elleri elime değdiğinde tüm bedenim titredi. Hiçbir şey yapmadık, yapmayacağız da çünkü ikimiz de bağlıyız. Ama o akşam eve dönerken arabada uzun uzun düşündüm; bazı ateşler hiç sönmüyor, sadece küllerinin altında usulca yanmaya devam ediyormuş. Bu tehlikeli anıyı kalbimin en derin köşesine gömdüm.', true, 'Aşk', 'Aşk', 1063, 149, 'approved', now() - interval '26371 minutes'),
  ('a9c02a68-5c9e-4600-9af9-9b4efc422976', (select id from public.profiles order by random() limit 1), 'Evliliğimizin canlanması için eşimle her ay birbirimize gizli bir sürpriz yapma sözü verdik ve bu bizim küçük oyunumuz oldu. Bu ay sıra bendeydi; eve onun en sevdiği parfümü sıkıp, loş ışıkta, elimde iki kadehle bekledim. Kapıdan girdiğinde durakladı, gözlerindeki o ışıltıyı yıllardır görmemiştim, çantasını düşürdü neredeyse. O gece telefonlarımızı başka odaya koyduk ve sadece birbirimize odaklandık; konuştuk, dans ettik, ilk günkü gibi birbirimizi keşfettik. Bu küçük oyun, evliliğimizi yeniden alev aldı. İtirafım: tutku kendi kendine gelmiyor, onu beslemek, ona emek vermek gerekiyor. Bizim bu gizli sürpriz oyunumuz, on yıllık evliliğimizin en güzel buluşu oldu.', true, 'Fantezi', 'Fantezi', 852, 99, 'approved', now() - interval '7665 minutes'),
  ('d5d49543-233f-4a2f-9ffe-a3afa3a59921', (select id from public.profiles order by random() limit 1), 'Yıllardır en yakın arkadaşımla kardeş gibiydik ama son aylarda ona bakışım değişti; gülüşünü, saçını arkaya atışını, konuşurken dudağını ısırışını fark eder oldum ve içimde tarifsiz bir çekim büyüdü. Geçen gece bir filmde yan yana otururken elleri elime değdi ve ben elimi çekemedim, o da çekmedi; parmaklarımız usulca birbirine dolandı, kalbim göğsümden çıkacaktı, nefesimi tutmuştum. Hiçbir şey konuşmadık ama o an aramızda bir şeyin değiştiğini ikimiz de hissettik. Şimdi her buluşmamızda o gerilim havada asılı duruyor. Bu arkadaşlığı riske atmaya değer mi, yoksa bu tatlı belirsizlik içinde mi kalmalıyım? İçimdeki bu yangını daha fazla saklayamıyorum.', true, 'Aşk', 'Aşk', 822, 104, 'approved', now() - interval '13778 minutes'),
  ('94db8ac7-93a0-4cee-ad7d-42d8a1ddcf13', (select id from public.profiles order by random() limit 1), 'Eşim çok klasik biriydi, hep aynı düzen, aynı rutin. Geçen yıldönümümüzde onu şaşırtmak istedim; bir otelde oda tuttum, ona sadece bir adres ve bu akşam saat sekizde, kapıyı çal, sürpriz seni bekliyor yazan bir not bıraktım. Geldiğinde kapıyı mumlarla, müzikle ve yepyeni bir cesaretle açtım. Yüzündeki o şaşkınlık ve hayranlık paha biçilemezdi, sen misin gerçekten dedi. O gece ikimiz de farklı insanlar olduk, yıllardır içimizde sakladığımız çapkınlığı, oyunbazlığı ortaya çıkardık. Sabah otelden çıkarken ellerimiz birbirine kenetliydi, gencecik âşıklar gibiydik. İtirafım: bazen tutkuyu yeniden ateşlemek için cesur olmak, rutini kırmak yetiyor. O gece evliliğimizin yeni bir başlangıcı oldu.', true, 'Fantezi', 'Fantezi', 685, 419, 'approved', now() - interval '29685 minutes'),
  ('2aebb32b-3bfb-47d2-aaac-536dcf8aae90', (select id from public.profiles order by random() limit 1), 'Tatilde, deniz kenarındaki bir barda biriyle tanıştım; gözleri öyle derin, gülüşü öyle çekiciydi ki bütün gece konuştuk, dünya durdu sanki. Aramızdaki o elektrik o kadar yoğundu ki birbirimize değmeden bile bir yakınlık hissettik. Gece sahilde yürüdük, yıldızların altında uzun uzun baktık birbirimize, rüzgâr saçlarını savuruyordu. Hiçbir şey yaşanmadı ama o gerilim, o anın büyüsü bende derin bir iz bıraktı. Tatil bitti, ayrı şehirlere döndük ama hâlâ o geceyi, o bakışı düşünüyorum. Bazen birkaç saatlik bir karşılaşma, yıllarca süren ilişkilerden daha derin iz bırakıyormuş. O yabancının adını bile tam bilmiyorum ama o geceyi asla unutmayacağım.', true, 'Aşk', 'Aşk', 261, 39, 'approved', now() - interval '16456 minutes'),
  ('c01f08a7-7750-4fd9-865e-a48152896679', (select id from public.profiles order by random() limit 1), 'Eşimle aramızdaki tutku sönmeye başlayınca, bir akşam oturup en gizli hayallerimizi birer kâğıda yazıp bir kavanoza atalım dedik. Sonra her hafta sonu kavanozdan bir kâğıt çekip o hayali gerçekleştirme oyunu kurduk. İlk çektiğimiz kâğıt benimkiydi ve eşimin yüzündeki o muzip gülümsemeyle o akşam ikimiz de yıllar sonra ilk kez böyle gülüp heyecanlandık. Bu oyun, yatak odamızı bir macera alanına çevirdi; her hafta sonu bir sürpriz, bir keşif. Yıllardır içimizde sakladığımız o çapkın yanlarımızı birbirimize gösterdik. İtirafım: evliliği canlı tutan şey, birbirinin hayallerine cesaret edebilmekmiş. O kavanoz, evimizin en değerli hazinesi oldu.', true, 'Fantezi', 'Fantezi', 577, 397, 'approved', now() - interval '14497 minutes'),
  ('3f8bef2a-3436-4981-b2f3-ad361e703a91', (select id from public.profiles order by random() limit 1), 'İş yerinde yeni bir yönetici geldi; karizmatik, kendinden emin, her toplantıda gözlerim ona kayıyor. Profesyonel davranmaya çalışıyorum ama o bana bir şey sorduğunda kelimelerim dolanıyor, yüzüm kızarıyor. Geçen gün asansörde yalnız kaldık, dar alanda kolonyasının kokusu burnuma doldu ve içimden bir sıcaklık geçti, dilim tutuldu. O da bana öyle bir baktı ki, sanki o da aynı şeyi hissediyordu. İkimiz de bekarız ama iş yeri ilişkisi olur mu diye çekiniyorum. Her sabah onu görmek için işe daha bir hevesle gidiyorum, masamdan onu izliyorum. Bu çekimi bir süre daha saklayabilir miyim, yoksa bu yangın beni ele mi verecek? İçimdeki bu heyecan yıllar sonra ilk kez bu kadar canlı.', true, 'Aşk', 'Aşk', 133, 135, 'approved', now() - interval '30615 minutes'),
  ('dfedb6d6-00ad-4f07-ae8d-ad4722fe3d96', (select id from public.profiles order by random() limit 1), 'Eşimle uzun zamandır aramız mesafeliydi, ikimiz de iş ve çocuklarla yorgun düşmüştük. Bir gece çocuklar uyuyunca, ona yıllardır söylemeye çekindiğim bir hayalimi fısıldadım. Önce bir an sessiz kaldı, sonra gözlerinde bir kıvılcım belirdi ve beni kendine çekti. O gece sanki ilk randevumuzdaymışız gibi heyecanlandık, kıkırdadık, birbirimizi yeniden keşfettik. Sabah uyandığımda yıllardır olmadığı kadar mutluydu, bana farklı bakıyordu. Meğer ikimiz de aynı özlemi taşıyormuşuz ama söylemeye korkmuşuz. İtirafım: bir evlilikte en tehlikeli şey suskunluk, en güzel şey ise cesaretle paylaşılan bir arzu. O geceden sonra aramızdaki o eski ateş yeniden yandı ve hiç sönmedi.', true, 'Fantezi', 'Fantezi', 185, 79, 'approved', now() - interval '10677 minutes'),
  ('ed66229f-7e8d-442a-a0b7-eb9ba91471fe', (select id from public.profiles order by random() limit 1), 'Komşumun, sık sık misafirliğe gelen kuzeni var; her geldiğinde apartman girişinde bir bahaneyle karşılaşıyoruz, sohbetlerimiz uzuyor, gözlerimiz birbirini arıyor. Bekârım, o da öyle ama bir türlü adım atamıyoruz, sadece o tatlı gerilimi yaşıyoruz. Geçen gün yağmurda aynı saçağın altında mahsur kaldık, omuz omuza, nefeslerimiz birbirine karışıyordu ve o an dünyada başka kimse yokmuş gibi hissettim. Bana telefonunu uzattı, numaranı yaz dedi ve elim titreyerek yazdım. O geceden beri her mesajıyla içim kıpır kıpır oluyor, ilk kez bu kadar heyecanlı hissediyorum. Bazen kader insanları en beklenmedik yerde, bir yağmurun altında karşılaştırıyormuş. Bu defa kaçırmamaya kararlıyım.', true, 'Aşk', 'Aşk', 7045, 2035, 'approved', now() - interval '29677 minutes'),
  ('621eb011-ba6c-4319-851c-0f50ce71ebf6', (select id from public.profiles order by random() limit 1), 'Yıllardır evliyiz ve eşim her zaman çok ciddi, çok ölçülü biriydi; ben de aramızdaki o oyunbazlığın hiç olmamasından yakınırdım. Geçen ay birlikte uzun bir yolculuğa çıktık ve arabada, sadece ikimizken, ona içimden geçeni, hayallerimi, isteklerimi anlattım. Beni dinledikçe gülümsemesi büyüdü ve sonunda bana neden bunca yıl bu kadar utandın dedi. O yolculuktan sonra eşim sanki değişti; daha cesur, daha çapkın, daha tutkulu oldu. Meğer o ciddi maskenin altında oyunbaz bir ruh saklıymış, sadece ben fitili ateşlemeyi beklemişim. İtirafım: insanlar değişmez demeyin, bazen sadece güvenli bir kapı aralanmasını beklerler. O yolculuk, evliliğimizin en güzel dönüm noktası oldu.', true, 'Fantezi', 'Fantezi', 9714, 5392, 'approved', now() - interval '33012 minutes'),
  ('e01cf13c-4e82-4bf5-8760-f1d54a904ab6', (select id from public.profiles order by random() limit 1), 'Lise yıllarında deli gibi âşık olduğum biri vardı ama hiç söyleyememiştim, o gidip başkasıyla olmuştu. Yıllar sonra, ikimiz de bekarken, bir sınıf buluşmasında karşılaştık ve o eski yangın bir anda küllerinden doğdu. Bütün gece sadece birbirimizle konuştuk, eski günleri andık ve o ben sana âşıktım ama söyleyemedim dediğinde dünyam durdu; meğer ikimiz de aynı şeyi yıllarca saklamışız. Gece biterken arabaya kadar yürüdük, kapıda bir an birbirimize öyle yakın durduk ki nefeslerimiz birbirine karıştı, kalbim yerinden fırlayacaktı. O gece bir telefon numarası ve yeni bir başlangıcın umuduyla ayrıldık. Bazen aşk, on yıl sonra bile seni bulmaya geliyormuş. Bu sefer kaçırmayacağım.', true, 'Aşk', 'Aşk', 2619, 496, 'approved', now() - interval '5538 minutes'),
  ('ee70b6b1-62f8-4947-af0c-3d0576a89f1e', (select id from public.profiles order by random() limit 1), 'Eşimle bir akşam oturup, ilişkimize biraz heyecan katmak için birbirimize gizli notlar bırakma oyunu icat ettik. Sabah onun ceketinin cebine, akşam yastığının altına çapkın, tatlı notlar bırakıyoruz; bu akşam beni bekle ya da bugün seni çok düşündüm gibi. Bu küçük oyun, evimizi bir flört sahnesine çevirdi; her gün bir not bulma heyecanı, her akşam bir sürpriz. Yıllardır kaybettiğimiz o gençlik heyecanını yeniden bulduk, birbirimize yeniden âşık olduk. Meğer evliliği taze tutmak için büyük jestler gerekmiyormuş, küçük bir kâğıt parçası bile yetiyormuş. İtirafım: bizim bu gizli not oyunumuz, yatak odamızı ve evliliğimizi yeniden alev aldı. Çiftlere tavsiyem, küçük sürprizlerin gücünü hafife almayın.', true, 'Fantezi', 'Fantezi', 596, 353, 'approved', now() - interval '25989 minutes'),
  ('d80475f2-c668-40cf-81b4-f1e8bbafc135', (select id from public.profiles order by random() limit 1), 'Yeni taşındığım apartmanda, karşı dairede yaşayan biriyle her sabah aynı anda çöp atmaya çıkıyoruz ve bu tesadüf giderek bir oyuna dönüştü; gülümsemeler, kısa sohbetler, birbirimizi arar olmamız. Geçen gün elimde poşetlerle düşürdüm, eğilip yardım etti ve elimiz değdiğinde ikimiz de bir an durduk, gözlerimiz kilitlendi, zaman durdu. O an içimde yıllardır hissetmediğim bir heyecan patladı. Bana kahve içmeye ne dersin dedi ve ben utangaç bir evetle karşılık verdim. Bu akşam ilk buluşmamız ve şimdiden ne giyeceğimi düşünüp duruyorum, içim kıpır kıpır. Bazen aşk en sıradan bir anda, bir çöp poşetinin başında başlıyormuş. Bu heyecanı çok özlemişim.', true, 'Aşk', 'Aşk', 881, 89, 'approved', now() - interval '796 minutes'),
  ('92f8c56a-e5fd-4853-89d9-73c29321b0e8', (select id from public.profiles order by random() limit 1), 'Evlilikte yıllar geçince tutkunun azaldığını fark ettik ve eşimle bir karar aldık; her cuma akşamı bizim gecemiz, telefon yok, çocuklar erken yatar, sadece ikimiz. İlk cuma çekingendik ama birkaç hafta sonra o akşamları iple çeker olduk; bazen dans ediyoruz, bazen oyunlar oynuyoruz, bazen sadece mum ışığında sarılıp konuşuyoruz. Bu ritüel, evliliğimizin can damarı oldu; haftanın geri kalanı ne kadar yorucu olursa olsun, o cuma gecesini bekliyoruz. Eşimin gözlerindeki o ışıltı, dokunuşundaki o heyecan geri geldi. İtirafım: tutkuyu canlı tutmak bir tesadüf değil, bir seçim ve emekmiş. Bizim cuma gecelerimiz, yıllardır kurduğumuz en güzel düzen oldu; herkese tavsiye ederim.', true, 'Fantezi', 'Fantezi', 2923, 869, 'approved', now() - interval '19010 minutes'),
  ('2cb31a19-b755-4253-89ec-f36a08554cd2', (select id from public.profiles order by random() limit 1), 'İş gezisinde, otelin barında biriyle tanıştım; konuşması, gülüşü, bana bakışı o kadar etkileyiciydi ki saatlerin nasıl geçtiğini anlamadık. Aramızda öyle yoğun bir çekim vardı ki, sadece konuşmak bile baş döndürücüydü, her kelimesinde içim ürperdi. Gece geç saatte asansöre kadar yürüdük ve kapı kapanmadan önce o son bakış, o havadaki gerilim hâlâ aklımdan çıkmıyor. Hiçbir şey yaşanmadı, ertesi gün ayrı şehirlere döndük ama o bir gecelik elektrik bende derin bir iz bıraktı. İkimiz de bağlıydık, bu yüzden bir çizgi çektik ama o an, o yakınlık unutulacak gibi değildi. Bazen hayat sana ne istediğini, bir yabancının gözlerinde hatırlatıyormuş. O geceyi bir sır olarak saklıyorum.', true, 'Aşk', 'Aşk', 1379, 184, 'approved', now() - interval '7562 minutes'),
  ('ff2d3472-c911-4107-8d85-52d23284401f', (select id from public.profiles order by random() limit 1), 'Eşim bana her zaman ben romantik değilim derdi ama geçen sevgililer gününde beni yerle bir etti. Eve geldiğimde tüm ev karanlıktı, sadece bir yol boyunca mumlar yanıyordu ve o yolun sonunda, en güzel hâliyle, elinde bir gülle beni bekliyordu. O kadar şaşırdım ki ağladım neredeyse. O gece, yıllardır görmediğim bir tutkuyla, bir oyunbazlıkla beni sardı; sanki başka biriyle, gizemli bir yabancıyla tanışıyordum. Meğer içinde kocaman bir romantik saklıymış, sadece doğru anı bekliyormuş. İtirafım: insanları olduğunu sandığınız kalıba sokmayın, çünkü en sıradan görünen eşinizin içinde sizi büyüleyecek bir ateş olabilir. O gece, evliliğimizin en sıcak gecesiydi ve hâlâ o anın sıcaklığını taşıyorum.', true, 'Fantezi', 'Fantezi', 571, 80, 'approved', now() - interval '10144 minutes'),
  ('61be0010-7955-4c4e-8897-edb98750e2ae', (select id from public.profiles order by random() limit 1), 'Yoga dersinde tanıştığım biri var; sakin, gizemli, her hareketinde bir zarafet. Dersten sonra çay içerken sohbetlerimiz uzuyor, gözlerimiz birbirini arıyor, aramızda söze dökülmeyen bir yakınlık büyüyor. Geçen gün denge hareketinde sallandım, elimden tuttu ve o temasta içimden bir akım geçti, yüzüm kızardı. Bana bu akşam bir şeyler içelim mi dedi ve ben hevesle kabul ettim. Yıllardır kimse içimde bu kadar heyecan uyandırmamıştı; her ders gününü, onu göreceğim diye iple çekiyorum. Bazen aşk en sakin, en beklenmedik yerde, bir nefes egzersizinin ortasında doğuyormuş. İçimdeki bu kıpırtıyı çok özlemişim, bu defa peşinden gitmeye kararlıyım.', true, 'Aşk', 'Aşk', 659, 409, 'approved', now() - interval '32005 minutes'),
  ('1601d8ee-ab17-4fb2-aa23-81e9adc585df', (select id from public.profiles order by random() limit 1), 'Eşimle ortak bir hayalimiz vardı; bir gece, herkesin bizi tanımadığı bir şehirde, gizemli yabancılar gibi yeniden tanışmak. Geçen ay bunu gerçekleştirdik; ayrı ayrı bir otel barına gittik, sanki birbirimizi hiç tanımıyormuşuz gibi, baştan flört ettik. Eşim bana yabancı bir adam gibi yaklaştı, bir içki ısmarladı, ismimi sordu ve ben kıkırdayarak oyuna katıldım. O gece, yıllardır evli olduğumuz adamla yeniden, sıfırdan âşık olduk; her bakış, her dokunuş ilk günkü gibi heyecanlıydı. İtirafım: evliliği canlı tutmanın en eğlenceli yolu, ara sıra birbirinize yabancı olmakmış. O gece, on yıllık evliliğimizin en tutkulu, en unutulmaz anıydı. Bunu her çifte öneririm.', true, 'Fantezi', 'Fantezi', 618, 26, 'approved', now() - interval '34868 minutes'),
  ('c7f445b8-32cb-449b-ab2f-227aaf96fbcd', (select id from public.profiles order by random() limit 1), 'Üniversitede aynı projede çalıştığım biriyle, gece geç saatlere kadar kütüphanede kaldığımız bir dönem, aramızda tatlı bir gerilim oluştu. Yorgunluktan başını omzuma yasladığında, parfümünün kokusu burnuma dolduğunda kalbim deli gibi attı, kıpırdayamadım. Aramızda hiçbir şey konuşulmadı ama o yakınlık, o gece yarısı paylaşımları içimde bir yangın başlattı. Proje bitti, herkes dağıldı ama ben onu unutamadım. Geçen gün cesaretimi toplayıp ona seninle çalışmak hayatımın en güzel kısmıydı diye mesaj attım ve o ben de seni hep merak ettim diye cevap verdi. Şimdi ilk gerçek randevumuzu planlıyoruz. Bazen aşk, bir proje teslim tarihinin gölgesinde usulca büyüyormuş. İçim kıpır kıpır.', true, 'Aşk', 'Aşk', 701, 270, 'approved', now() - interval '29537 minutes'),
  ('e789a359-14b6-4f63-b20d-79f02be730f6', (select id from public.profiles order by random() limit 1), 'Eşimle yıllardır süren tutkumuzun sırrı, asla rutine teslim olmamamız. Her ay birimiz diğerine bir tema belirliyoruz; bazen bir kostüm gecesi, bazen bir dans gecesi, bazen sadece yıldızların altında bir piknik. Bu ay eşim bir gece bana en güzel hâlinle, en sevdiğim parfümünle beni çatıda bekle diye not bıraktı. Çatıya çıktığımda kurmuş olduğu o romantik düzeni görünce nefesim kesildi; battaniyeler, mumlar, şehrin ışıkları. O gece şehrin üstünde, sadece ikimiz, yeniden âşık olduk. İtirafım: evliliği bir aşk hikâyesi gibi yaşamak bir seçim ve biz bu seçimi her gün yeniliyoruz. Bizim bu küçük tema oyunlarımız, evliliğimizi bir maceraya çevirdi; yıllar geçse de ateşimiz hiç sönmedi.', true, 'Fantezi', 'Fantezi', 129, 46, 'approved', now() - interval '7998 minutes'),
  ('3d273c17-6f34-4bec-8cfb-a3ff5660cc3b', (select id from public.profiles order by random() limit 1), 'Komşu apartmandaki spor salonunda her akşam koştuğum saatte, hep aynı kişiyle göz göze geliyoruz; gülümsemeler, başla selamlaşmalar derken, geçen gün koşu bandında yan yana düştük ve nefes nefese sohbet etmeye başladık. Konuşurken aramızdaki o uyum, o çekim öyle güçlüydü ki egzersizin bittiğini bile fark etmedik. Bana su uzattı, elim eline değdi ve o an içimde tuhaf bir sıcaklık yayıldı, yüzüm kızardı. Bir kahve içmeye ne dersin dedi ve ben evet demeden duramadım. Bekarım, o da öyle ve yıllar sonra ilk kez biri içimde bu heyecanı uyandırdı. Her akşam o salona, koşmak için değil onu görmek için gidiyorum artık. Bu defa cesur olacağım.', true, 'Aşk', 'Aşk', 1105, 88, 'approved', now() - interval '27334 minutes'),
  ('d5b4f0f6-c0a2-46c1-bde5-8cac96301e65', (select id from public.profiles order by random() limit 1), 'Eşimle yıllardır aynı yatakta yatıyorduk ama tutku azalmıştı. Bir gün bir dergide okuduğum öneriyle, bir akşam ona bir randevu teklif ettim; sanki sevgiliymişiz gibi, ayrı evlerden çıkıp bir restoranda buluşalım dedim. O akşam en güzel hâlimle hazırlandım, o da takım elbisesini giydi ve restoranda buluştuğumuzda sanki ilk randevumuzdaymışız gibi heyecanlandık, utandık, kıkırdadık. Yıllardır evli olduğum adamı yeniden tavlamak, yeniden flört etmek inanılmaz heyecanlıydı. O gece eve birlikte, el ele, gencecik âşıklar gibi döndük. İtirafım: evliliği canlı tutmak için bazen birbirinizi yeniden fethetmeniz gerekiyormuş. O randevu gecesi, evliliğimize yeniden tutku kattı ve artık her ay bir randevu gecesi yapıyoruz.', true, 'Fantezi', 'Fantezi', 1206, 542, 'approved', now() - interval '3639 minutes'),
  ('6da39fbf-fd46-4db9-b85c-6ad471f66171', (select id from public.profiles order by random() limit 1), 'İş yerindeki bir toplantıda, masanın karşısında oturan biriyle gözlerimiz sürekli buluşuyordu; o konuşurken ben onu izliyordum, ben konuşurken o bana odaklanıyordu ve aramızdaki o gerilim odada hissediliyordu sanki. Toplantı bitince koridorda yan yana yürüdük, kolumuz değdi ve o an ikimiz de bir an durduk, sustuk. Bana bu projede seninle çalışmak için sabırsızlanıyorum dedi ama gözleri başka bir şey söylüyordu. Bekarız ikimiz de ama iş ortamında adım atmaktan çekiniyoruz. Her sabah onu göreceğim diye işe bir heyecanla gidiyorum, her ortak toplantı bir buluşma gibi. Bu tatlı gerilimi daha ne kadar taşıyabilirim bilmiyorum; içimdeki bu kıvılcımı bir gün ateşe çevirecek miyim merak ediyorum.', true, 'Aşk', 'Aşk', 1695, 354, 'approved', now() - interval '3196 minutes'),
  ('89bb11ad-e7ad-4a09-bfe9-2b6c3a0b113c', (select id from public.profiles order by random() limit 1), 'Eşimle bir akşam, çocuklar yatınca, gençlik fotoğraflarımıza bakıyorduk ve o günlerdeki tutkumuzu, çılgınlığımızı özlediğimizi fark ettik. O gece bir karar aldık; o eski çılgın çifte geri dönmek için ne gerekiyorsa yapacaktık. Müziği açtık, ışıkları kıstık, salonun ortasında dans ettik, güldük, birbirimizi yıllar önceki gibi öptük. Sanki zaman geri sarmış, yeniden yirmili yaşlarımızdaki o ateşli âşıklara dönmüştük. Sabaha kadar uyumadık, konuştuk, sevdik, hayaller kurduk. İtirafım: yıllar tutkuyu öldürmüyor, biz onu rutinin altına gömüyoruz; biraz çabayla yeniden çıkarmak mümkün. O geceden sonra her hafta dans ediyoruz ve evliliğimiz yeniden gençleşti; herkese o eski şarkıları açmayı öneririm.', true, 'Fantezi', 'Fantezi', 1562, 449, 'approved', now() - interval '28032 minutes'),
  ('b6c75837-3051-4a4a-9c5c-213bcf032dae', (select id from public.profiles order by random() limit 1), 'Sahilde sabah koşusu yaparken her gün aynı kişiyle karşılaşıyordum; bir gülümseme, bir baş selamı derken bir sabah ikimiz de aynı yerde mola verdik ve sohbet başladı. Deniz kenarında, güneş doğarken yaptığımız o sohbet o kadar doğal, o kadar sıcaktı ki saatlerin geçtiğini anlamadık. Bana bir kahve içelim mi dedi ve o sabah, terli ve nefes nefese, hayatımın en güzel kahvesini içtik. Gözlerindeki o içtenlik, gülüşündeki o sıcaklık beni büyüledi. Yıllardır kalbim bu kadar hızlı atmamıştı. Şimdi her sabah, koşmak için değil, onu görmek için o sahile gidiyorum. Bazen aşk, gün doğumunda, deniz kıyısında, ter içinde başlıyormuş. Bu heyecanı çok özlemişim ve bu defa kaçırmayacağım.', true, 'Aşk', 'Aşk', 636, 74, 'approved', now() - interval '7978 minutes'),
  ('8fed0efa-ceda-4438-bd92-101cdd3fdf2a', (select id from public.profiles order by random() limit 1), 'Eşimle uzun bir aradan sonra, çocukları akrabaya bırakıp bir hafta sonu kaçamağı yaptık; sadece ikimiz, bir dağ evinde, şömine başında. İlk akşam şöminenin önünde, battaniyeye sarılı, şarap içerken yıllar önceki o ilk günkü heyecanı yeniden yaşadık. O bana öyle bir baktı ki, sanki yeniden tanışıyorduk; konuştuk, güldük, birbirimizi yeniden keşfettik. Telefon yok, çocuk yok, iş yok; sadece biz ve aramızdaki o yeniden alevlenen ateş. O hafta sonu, evliliğimizin son yıllarından daha değerliydi, eve bambaşka bir çift olarak döndük. İtirafım: tutkuyu yeniden bulmak için bazen dört duvardan, rutinden, ekranlardan kaçmak yetiyormuş. O dağ evi, kalbimizdeki ateşi yeniden yaktı ve artık her yıl o kaçamağı tekrarlıyoruz.', true, 'Fantezi', 'Fantezi', 1045, 425, 'approved', now() - interval '23310 minutes'),
  ('f6a662c2-0c4a-4297-bee0-d1cccdc69731', (select id from public.profiles order by random() limit 1), 'Kuaförde tanıştığım biriyle, bekleme sırasında başlayan sohbet öyle keyifliydi ki ikimiz de sıramızın gelmesini istemedik. Espriler, gülüşmeler, ortak zevkler derken aramızda anında bir kıvılcım çaktı. Çıkarken bana numaranı alabilir miyim dedi ve ben kıpkırmızı olarak verdim. O akşam ilk mesajı geldiğinde, telefonu elimden bırakamadım, lise çağındaki gibi heyecanlandım. Birkaç gündür sürekli yazışıyoruz ve her mesajıyla içim kıpır kıpır oluyor, gülümsemeden duramıyorum. Bekarım ve yıllardır biri içimde bu kadar heyecan uyandırmamıştı. Bu hafta sonu ilk buluşmamız ve şimdiden ne giyeceğimi düşünüyorum. Bazen aşk, en sıradan bir bekleme sırasında, hiç ummadığın anda kapını çalıyormuş.', true, 'Aşk', 'Aşk', 297, 187, 'approved', now() - interval '12758 minutes'),
  ('7135c494-55ac-463b-9172-4b93a96c5d12', (select id from public.profiles order by random() limit 1), 'Evliliğimizin onuncu yılında eşim bana, gençken hayalini kurduğumuz ama hiç yapamadığımız bir şeyi sürpriz olarak hazırladı; bir gece için tuttuğu, manzaralı bir otel odası, şampanya, gül yaprakları ve yıllardır görmediğim o muzip bakış. Kapıyı açtığımda nefesim kesildi, sen misin gerçekten dedim. O gece, on yıllık eşimle yeniden, sıfırdan âşık olduk; her dokunuş, her bakış ilk günkü gibi elektrik yüklüydü. Yıllardır içinde sakladığı o tutkulu, oyunbaz adamı o gece tanıdım. İtirafım: evlilik bir alev sönmesi değil, beslenmeyi bekleyen bir ateşmiş. O sürpriz gece, evliliğimize yeniden can verdi ve hâlâ o gecenin sıcaklığını her gün hissediyoruz. Eşinize bir sürpriz yapın, çünkü en güzel anılar cesaretle kuruluyor.', true, 'Fantezi', 'Fantezi', 301, 12, 'approved', now() - interval '35787 minutes'),
  ('00ac64e7-f18c-4bfa-9fc4-7a5eed72f700', (select id from public.profiles order by random() limit 1), 'Eski bir arkadaşımla, yıllar sonra sosyal medyada tekrar bağlantı kurduk ve mesajlaşmalarımız giderek samimileşti, derinleşti. Her gece geç saatlere kadar konuşuyoruz, en gizli düşüncelerimizi paylaşıyoruz ve aramızda ekranların ötesine geçen bir yakınlık büyüyor. Geçen gün görüntülü konuştuk ve onu yıllar sonra ekranda görünce kalbim deli gibi attı, gülüşü hiç değişmemişti. İkimiz de bekarız ve farklı şehirlerdeyiz ama bu uzaklık, aramızdaki çekimi daha da artırıyor sanki. Gelecek hafta beni görmeye geliyor ve o günü iple çekiyorum, geceleri uykum kaçıyor. Bazen aşk, yıllar sonra bir mesajla yeniden alevleniyor, mesafeleri bile aşıyormuş. İçimdeki bu heyecanı yıllardır hissetmemiştim; bu defa kaybetmek istemiyorum.', true, 'Aşk', 'Aşk', 4296, 258, 'approved', now() - interval '6554 minutes'),
  ('5cff4491-b1d4-4521-8119-234e44a9971e', (select id from public.profiles order by random() limit 1), 'Eşim çok mesafeli, çok kontrollü biriydi; aramızdaki tutku hep ölçülü, hep tahmin edilebilirdi. Bir tatilde, sahilde el ele yürürken, ona içimden geçen tüm hayalleri, tüm istekleri çekinmeden anlattım. Beni dinledikçe gözlerindeki o ışık değişti ve o akşam bambaşka biri oldu; cesur, tutkulu, oyunbaz. Meğer o kontrollü dış görünüşün altında, salıvermeyi bekleyen ateşli bir ruh saklıymış. O tatilden sonra evliliğimiz tamamen değişti; artık birbirimize her şeyi söyleyebiliyor, her hayali paylaşabiliyoruz. İtirafım: bir insanı gerçekten tanımak, onun en gizli arzularına ortak olabilmekmiş. O sahil yürüyüşü, aramızdaki duvarları yıktı ve evliliğimize hiç beklemediğimiz bir tutku, bir yakınlık getirdi. Konuşmak, paylaşmak her şeyi değiştiriyor.', true, 'Fantezi', 'Fantezi', 203, 22, 'approved', now() - interval '4654 minutes'),
  ('7921cd01-5945-4892-b747-da1b7aa442c1', (select id from public.profiles order by random() limit 1), 'Bir konserde, kalabalığın içinde yanımda duran biriyle, müzik eşliğinde gözlerimiz buluştu ve o anki elektrik tarif edilemezdi. Şarkı boyunca yan yana, omuz omuza, aynı ritimle salındık ve aramızda sözsüz bir yakınlık doğdu. Konser bitince çıkışta yine karşılaştık, gülümsedi ve seni bütün gece izledim dedi; ben de utanarak ben de seni dedim. O gece şehir ışıklarının altında uzun uzun yürüdük, konuştuk, güldük, birbirimize sokulduk. Hiçbir şey planlamadık ama o gece bende derin bir iz bıraktı. Şimdi her gün mesajlaşıyoruz ve içimdeki o konser akşamının heyecanı hiç dinmedi. Bazen aşk, sevdiğin bir şarkının nakaratında, bir kalabalığın ortasında doğuyormuş. O geceyi hayatım boyunca unutmayacağım.', true, 'Aşk', 'Aşk', 874, 492, 'approved', now() - interval '3369 minutes'),
  ('a537fa6c-0487-4a1c-ada2-e1dfbf8e5e9c', (select id from public.profiles order by random() limit 1), 'Eşimle bir akşam, ilişkimize heyecan katmak için birbirimize gizli arzularımızı yazdığımız mektuplar yazdık ve bunları karşılıklı okuduk. O mektupları okurken hem utandık hem heyecanlandık, çünkü yıllardır birbirimizden sakladığımız hayallerimiz meğer birbirine ne kadar da benziyormuş. O gece, o mektuplardaki hayalleri tek tek konuştuk, güldük, planladık ve yatak odamız bir maceraya dönüştü. Meğer ikimiz de aynı şeyleri istiyormuş ama söylemeye cesaret edememişiz. İtirafım: bir evlilikte en romantik şey, birbirinize en gizli arzularınızı çekinmeden anlatabilmekmiş. O mektuplar hâlâ saklı duruyor ve ara sıra yeniden okuyup o geceyi hatırlıyoruz. Tutku, paylaşılan hayallerle besleniyormuş; biz bunu çok geç öğrendik ama artık her gün yaşıyoruz.', true, 'Fantezi', 'Fantezi', 1252, 290, 'approved', now() - interval '214 minutes'),
  ('46390bcd-0ab6-4d3f-b95a-94ad5c854367', (select id from public.profiles order by random() limit 1), 'İş seyahatinde, otelin asansöründe biriyle karşılaştım ve o dar alanda, birkaç saniyelik o yolculukta aramızda öyle yoğun bir çekim oluştu ki nefesim kesildi. Aynı kata çıktık, koridorda yan yana yürürken bir an durduk, gözlerimiz kilitlendi ve havadaki o gerilim elle tutulur gibiydi. Bana bir şeyler içmek ister misin dedi ve ben kalbim küt küt atarak kabul ettim. O gece otelin barında saatlerce konuştuk, güldük, birbirimize yaklaştık ama bir çizgi çektik çünkü ikimiz de bağlıydık. O bir gecelik yoğunluk, o tatlı işkence hâlâ aklımdan çıkmıyor. Bazen hayat, bir asansör yolculuğunda sana ne kadar tutkulu hissedebileceğini hatırlatıyormuş. O geceyi kalbimin bir köşesine, gizli bir hatıra olarak gömdüm.', true, 'Aşk', 'Aşk', 1585, 666, 'approved', now() - interval '26180 minutes'),
  ('4dcdc925-85c2-48ea-99cd-a9851eca4aaa', (select id from public.profiles order by random() limit 1), 'Evliliğimizde tutkuyu canlı tutmanın sırrını bulduğumuzu düşünüyorum; her yıldönümünde, ilk tanıştığımız o günü canlandırıyoruz. Aynı kafeye gidiyor, aynı masaya oturuyor, sanki birbirimizi yeni tanıyormuş gibi flört ediyoruz. Bu yıl eşim oyuna öyle bir girdi ki, bana yabancı bir adam gibi yaklaştı, bir kahve ısmarladı, ismimi sordu ve ben kıkırdayarak oyuna katıldım. O gün, yıllar önce âşık olduğumuz o iki gence yeniden dönüştük; her bakış, her gülüş ilk günkü gibi heyecanlıydı. İtirafım: evliliği bir aşk hikâyesi gibi yaşamayı seçtik ve her yıl o hikâyenin ilk sayfasını yeniden yazıyoruz. Bu ritüel, aramızdaki ateşi hiç söndürmedi; herkese ilk buluşmasını yeniden canlandırmayı öneririm.', true, 'Fantezi', 'Fantezi', 2082, 1170, 'approved', now() - interval '13475 minutes'),
  ('d9b5d7b1-1cbe-4ceb-aa54-ab40f168198c', (select id from public.profiles order by random() limit 1), 'Komşumun düzenlediği bir ev partisinde, kalabalığın içinde biriyle göz göze geldim ve o an dünyada başka kimse kalmadı sanki. Bütün gece bir köşede, fısıltıyla konuştuk, kahkahalar attık ve aramızda anında bir yakınlık, bir çekim doğdu. Bahçeye çıktık, yıldızların altında yan yana oturduk ve omzu omzuma değdiğinde içimden bir ürperti geçti, kalbim hızlandı. Hiçbir şey yaşanmadı ama o gece, o sohbet, o yakınlık bende derin bir iz bıraktı. Ayrılırken numaramı istedi ve elim titreyerek verdim. O geceden beri her gün mesajlaşıyoruz ve içimdeki o parti akşamının heyecanı hiç dinmedi. Bazen aşk, bir kalabalığın ortasında, hiç tanımadığın birinin gözlerinde başlıyormuş. Bu defa peşinden gideceğim.', true, 'Aşk', 'Aşk', 1665, 486, 'approved', now() - interval '16903 minutes'),
  ('3a18ec89-bd1c-4204-8e1f-386e7b62d2b7', (select id from public.profiles order by random() limit 1), 'Eşimle yıllar geçtikçe rutine saplandığımızı fark edince, bir karar aldık; ayda bir, hiç gitmediğimiz bir yere, sırf ikimiz için küçük bir kaçamak yapacaktık. İlk kaçamağımızda, kimsenin bizi tanımadığı küçük bir kasabada, sanki yeni tanışan iki âşık gibi davrandık; el ele dolaştık, isimsiz bir handa kaldık, sabaha kadar konuştuk. O gece, yıllardır evli olduğum adama yeniden âşık oldum; uzaktan, rutinden, sorumluluklardan kaçınca aramızdaki o ilk günkü ateş yeniden tutuştu. İtirafım: evliliği canlı tutmak için bazen sadece bir bavul ve cesaret yetiyormuş. O kaçamaklar bizim küçük sırrımız oldu ve her seferinde birbirimize yeniden âşık oluyoruz. Tutku, paylaşılan maceralarla besleniyormuş.', true, 'Fantezi', 'Fantezi', 6936, 595, 'approved', now() - interval '30694 minutes'),
  ('b38daf74-4a5c-44c4-ac35-b36f76858618', (select id from public.profiles order by random() limit 1), 'Yağmurlu bir günde, otobüs durağında aynı şemsiyenin altına sığındığımız biriyle başlayan sohbet, hayatımın akışını değiştirdi. Omuz omuza, yağmurun sesi eşliğinde konuşurken aramızda öyle sıcak, öyle doğal bir yakınlık oluştu ki otobüsün geldiğini fark etmedik bile. Bana bir kahve içelim mi, yağmur dinene kadar dedi ve ben hevesle kabul ettim. O kafede, camdan yağmuru izlerken saatlerce konuştuk, güldük, birbirimize sokulduk. Gözlerindeki o sıcaklık, gülüşündeki o içtenlik beni büyüledi. Yıllardır kalbim bu kadar hızlı atmamıştı. Şimdi her yağmur yağdığında o günü hatırlıyor, gülümsüyorum. Bazen aşk, bir yağmurun altında, paylaşılan bir şemsiyenin gölgesinde başlıyormuş. O günü asla unutmayacağım.', true, 'Aşk', 'Aşk', 444, 71, 'approved', now() - interval '27293 minutes'),
  ('f087de83-a933-460f-b138-fed49806f1c7', (select id from public.profiles order by random() limit 1), 'Eşimle ilişkimizdeki tutkuyu canlı tutmak için bir kural koyduk; her ay birimiz diğerini bir sürprizle şaşırtacak ve bu sürpriz asla tahmin edilebilir olmayacaktı. Bu ay eşim beni eve gelirken bir mesajla yönlendirdi; önce bir not, sonra bir gül, sonra bir adres... Sonunda çatı katında, mum ışığında, en güzel hâliyle beni bekliyordu. O kadar şaşırdım ki nefesim kesildi, yıllardır onu bu kadar romantik görmemiştim. O gece, evliliğimizin en tutkulu gecelerinden biri oldu; sanki gizemli bir yabancıyla buluşuyordum. İtirafım: evliliği bir maceraya çevirmek tamamen bizim elimizde ve biz bu macerayı her ay yeniden yazıyoruz. O sürpriz oyunları, aramızdaki ateşi hiç söndürmedi; tutku, sürprizlerle ve cesaretle besleniyormuş.', true, 'Fantezi', 'Fantezi', 524, 71, 'approved', now() - interval '4125 minutes'),
  ('23925c92-d989-4a2d-aea1-35b3565f9c12', (select id from public.profiles order by random() limit 1), 'Bir kitap kulübünde tanıştığım biriyle, ortak sevdiğimiz bir roman üzerine başlayan sohbet, giderek daha kişisel, daha derin bir hâl aldı. Her hafta o buluşmayı, onu göreceğim diye iple çekiyorum; konuşurken gözlerindeki o zekâ, o tutku beni büyülüyor. Geçen hafta aynı kitabı uzanırken ellerimiz değdi ve ikimiz de bir an durduk, gözlerimiz kilitlendi, kalbim hızlandı. Bana kahve içerken bu konuşmayı sürdürelim mi dedi ve ben hevesle kabul ettim. Bekarım ve yıllardır biri zihnimi ve kalbimi aynı anda bu kadar etkilememişti. Her kitap kulübü gününü, yeni bir buluşma gibi bekliyorum. Bazen aşk, paylaşılan bir kitabın sayfaları arasında, en zarif şekilde filizleniyormuş. Bu heyecanı çok özlemişim.', true, 'Aşk', 'Aşk', 667, 76, 'approved', now() - interval '23944 minutes'),
  ('d157f7d8-d0ee-46e2-83e3-1517738d91dc', (select id from public.profiles order by random() limit 1), 'Eşimle bir akşam, yıllardır içimizde sakladığımız hayalleri konuşmak için oturduk ve cesaretimizi toplayıp birbirimize en gizli isteklerimizi anlattık. Önce ikimiz de kıpkırmızı olduk ama sonra fark ettik ki yıllardır birbirimizden sakladığımız o arzular meğer ne kadar da uyumluymuş. O gece, o hayalleri konuşa konuşa gülerek, heyecanlanarak yeni bir oyun kurduk ve evliliğimiz bambaşka bir boyut kazandı. Meğer en büyük yakınlık, en utangaç olduğumuz konularda dürüst olabilmekmiş. İtirafım: çiftler birbirinden arzularını saklamasın, çünkü o suskunluk aranızdaki en güzel anları çalıyor. O gece, evliliğimizin en açık, en tutkulu gecesiydi ve o günden beri birbirimize her şeyi çekinmeden anlatabiliyoruz. Konuşmak, her şeyi alev aldı.', true, 'Fantezi', 'Fantezi', 9483, 2657, 'approved', now() - interval '17981 minutes'),
  ('f5601814-6dc6-4a78-96e3-664452f795e0', (select id from public.profiles order by random() limit 1), 'Tatildeyken, otelin havuz kenarında biriyle göz göze geldim ve o ilk bakışta aramızda öyle bir çekim oluştu ki gün boyu birbirimizi aradık. Akşam barda yan yana düştük ve sohbetimiz saatlerce sürdü; her kelimesinde içim ürperdi, her gülüşünde kalbim hızlandı. Gece sahilde yürüdük, ay ışığının altında uzun uzun konuştuk, birbirimize sokulduk, nefeslerimiz birbirine karıştı. O an, dünyada sadece ikimiz varmışız gibi hissettim. Tatil bitti, ayrı şehirlere döndük ama hâlâ her gün konuşuyoruz, o tatil aşkını sürdürmeye kararlıyız. Bazen aşk, bir tatilin sıcağında, bir havuz kenarında, bir bakışta başlıyormuş. O tatili, o yabancıyı asla unutmayacağım; belki de bu bir tatil aşkından fazlası olur.', true, 'Aşk', 'Aşk', 383, 85, 'approved', now() - interval '24857 minutes'),
  ('d566c32f-2fd9-4475-8dfa-df96d56e52d2', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin en güzel keşfi, birbirimize asla yabancılaşmamak için sürekli yeni şeyler denememiz oldu. Geçen ay, hiç yapmadığımız bir şeyi denedik; bir gece için rollerimizi değiştirdik, birbirimize hayalini kurduğumuz karakterler olduk ve o oyunun içinde kahkahalarla, heyecanla kaybolduk. O gece, yıllardır evli olduğumuz hâlde, birbirimizin hiç bilmediğimiz yanlarını keşfettik. Meğer ikimizin de içinde oyunbaz, cesur birer ruh saklıymış. İtirafım: evliliği canlı tutmanın sırrı, birlikte oyun oynamaktan, birlikte gülmekten, birlikte cesur olmaktan geçiyormuş. O rol oyunu, yatak odamızı bir tiyatro sahnesine, evliliğimizi bir maceraya çevirdi. Tutku, birlikte denenen yeni şeylerle besleniyormuş; biz bunu geç keşfettik ama artık her gün yaşıyoruz.', true, 'Fantezi', 'Fantezi', 6125, 1770, 'approved', now() - interval '3804 minutes'),
  ('6fa704c8-3bfd-4deb-9996-675c893daf8b', (select id from public.profiles order by random() limit 1), 'İş yerinde, projede birlikte çalıştığım biriyle, geç saatlere kadar süren mesai dönemlerinde aramızda tatlı bir yakınlık oluştu. Birlikte yenen geç akşam yemekleri, paylaşılan kahveler, yorgunlukta birbirimize yaslanmalarımız derken, aramızda söze dökülmeyen bir çekim büyüdü. Geçen gece, herkes gittikten sonra ofiste yalnız kaldık ve o an aramızdaki gerilim tavan yaptı; gözlerimiz kilitlendi, ikimiz de bir adım atmaktan korktuk ama o yakınlık nefesimizi kesti. Proje yakında bitecek ve onu kaybetmekten korkuyorum. Ona hislerimi açmalı mıyım, yoksa bu güvenli mesafeyi mi korumalıyım? Bekarız ikimiz de ama iş ilişkisi riskli. İçimdeki bu yangını daha fazla saklayamıyorum; her ortak mesai, bir randevu gibi geçiyor.', true, 'Aşk', 'Aşk', 574, 105, 'approved', now() - interval '18853 minutes'),
  ('b80e2fca-701a-483d-9e60-2fb366935ecb', (select id from public.profiles order by random() limit 1), 'Eşimle bir yıldönümünde, evliliğimize sürpriz katmak için ikimiz de birbirimizden habersiz aynı şeyi planlamışız; ben ona romantik bir akşam yemeği ayarlamışım, o da bana bir kaçamak hafta sonu. İkimiz de aynı akşam sürprizimizi açınca kahkahalarla güldük ve meğer yıllar geçse de birbirimizi ne kadar iyi tanıyormuşuz, ne kadar aynı şeyleri istiyormuşuz dedik. O hafta sonu hem benim yemeğimi yedik hem onun kaçamağına gittik; çifte sürprizle, çifte tutkuyla. O günler, evliliğimizin en romantik, en sıcak anlarındandı. İtirafım: birbirini gerçekten tanımak, yıllar geçse de aynı anda aynı sürprizi düşünebilmekmiş. O çifte sürpriz, aramızdaki bağın ne kadar güçlü olduğunu gösterdi ve evliliğimize yeniden tutku kattı.', true, 'Fantezi', 'Fantezi', 322, 133, 'approved', now() - interval '28726 minutes'),
  ('689b5fa1-b530-4aa3-a56c-47d68e5f5772', (select id from public.profiles order by random() limit 1), 'Eski bir okul arkadaşımla, mezuniyetimizden yıllar sonra bir düğünde karşılaştık ve o eski tanıdık gülüş, o aşina bakış içimde unuttuğumu sandığım bir heyecanı uyandırdı. Bütün düğün boyunca yan yana oturduk, eski anıları konuştuk, güldük ve o, ben okurken sana hep gizliden hayrandım dediğinde dünyam durdu; meğer ikimiz de aynı şeyi yıllarca saklamışız. Dans pistinde yavaş bir şarkıda yan yana geldik, ellerimiz birbirine kenetlendi ve o an, on beş yaşımdaki o utangaç heyecanı yeniden yaşadım. Gece biterken numaramızı paylaştık ve şimdi her gün mesajlaşıyoruz. Bazen aşk, yılları aşıp bir düğünün ortasında seni yeniden buluyormuş. Bu defa o eski cesaretsizliği tekrarlamayacağım; kalbimin sesini dinleyeceğim.', true, 'Aşk', 'Aşk', 365, 122, 'approved', now() - interval '1807 minutes'),
  ('5302e2fa-186f-4a7c-948a-5d899a44020b', (select id from public.profiles order by random() limit 1), 'Eşim çok utangaç biriydi ve ben aramızdaki tutkunun rutine teslim olmasından korkuyordum. Bir gün, ona güvenli bir ortam yaratmak için, ışıkları kıstım, en sevdiği müziği açtım ve hiç çekinmeden içimden geçenleri, hayallerimi anlattım. İlk başta kızardı, utandı ama sonra o da yavaş yavaş açıldı ve meğer içinde yıllardır biriken bir tutku, bir merak saklıymış. O gece, yıllarca tanıdığımı sandığım eşimin hiç bilmediğim, cesur, tutkulu yanını keşfettim. İtirafım: bazen sevdiğin insanın içindeki ateşi ortaya çıkarmak için sadece güvenli, yargısız bir alan yaratmak yetiyormuş. O geceden sonra eşim bambaşka biri oldu; daha açık, daha cesur, daha tutkulu. Konuşmak ve güven, evliliğimizi yeniden alev aldı; herkese sabırla, sevgiyle yaklaşmayı öneririm.', true, 'Fantezi', 'Fantezi', 369, 123, 'approved', now() - interval '392 minutes'),
  ('642539c9-82c0-47b6-b474-3a231d8ae569', (select id from public.profiles order by random() limit 1), 'Bir sanat galerisinde, aynı tabloya dakikalarca bakan biriyle, o tablo üzerine başlayan sohbet, beklenmedik bir yakınlığa dönüştü. Sanattan konuşurken gözlerindeki o tutku, o derinlik beni büyüledi ve aramızda anında bir bağ kuruldu. Galeriyi birlikte gezdik, her tabloda fikir alışverişi yaptık, kahkahalar attık ve bir an, dar bir koridorda yan yana geçerken omzumuz değdi, ikimiz de durduk, gözlerimiz kilitlendi. Bana bu sohbeti bir kahve eşliğinde sürdürelim mi dedi ve ben hevesle kabul ettim. Bekarım ve yıllardır biri zihnimi bu kadar uyarmamıştı. Şimdi her sergi açılışına birlikte gidiyoruz ve aramızdaki o galeri akşamının büyüsü hiç dinmedi. Bazen aşk, bir tablonun önünde, paylaşılan bir bakışta doğuyormuş.', true, 'Aşk', 'Aşk', 3240, 98, 'approved', now() - interval '6165 minutes'),
  ('941c5afc-e5e2-4b38-b7ce-bd5566c435ed', (select id from public.profiles order by random() limit 1), 'Eşimle uzun yıllardır birlikteyiz ve tutkumuzu canlı tutmanın sırrı, asla ev kıyafetleri ve rutine teslim olmamamız. Geçen hafta, sıradan bir salı akşamı, hiçbir özel gün olmadığı hâlde, eve gelirken bir mesaj attı; bu akşam beni en güzel hâlinle bekle, bir sürprizim var. Eve geldiğinde elinde çiçekler, gözlerinde o muzip ışık vardı ve o sıradan salı akşamını bir aşk gecesine çevirdi. O gece, yıllardır evli olduğumuz hâlde, gencecik âşıklar gibi heyecanlandık. İtirafım: tutku özel günleri beklemez, onu en sıradan günlerde, küçük sürprizlerle beslemek gerekir. Bizim bu beklenmedik akşamlarımız, evliliğimizi her gün taze tutuyor. Bir salı akşamı bile bir aşk gecesine dönüşebiliyorsa, hayat ne kadar güzel; herkese öneririm.', true, 'Fantezi', 'Fantezi', 1399, 110, 'approved', now() - interval '3137 minutes'),
  ('5d712ab7-2c13-481a-a5d2-d7c4f45df9ad', (select id from public.profiles order by random() limit 1), 'Sahaf dükkânında, tozlu raflar arasında aynı kitaba uzanırken ellerimiz değdi ve ikimiz de bir an durup gülümsedik. O kitabı sana bırakayım dedi ama ben bir kahve ısmarlarsan paylaşırız diye karşılık verdim ve o günden sonra hayatım değişti. O eski kitap kokulu dükkânda saatlerce konuştuk, ortak sevdiğimiz yazarları, hayalleri paylaştık ve aramızda anında bir kıvılcım çaktı. Gözlerindeki o derinlik, sesindeki o sıcaklık beni büyüledi, yıllardır kalbim bu kadar hızlı atmamıştı. Şimdi her hafta sonu o sahafta buluşuyoruz, kitap bahanesiyle ama aslında birbirimiz için. Bazen aşk, eski bir kitabın sayfaları arasında, hiç ummadığın bir anda gizleniyormuş. Bu defa o kıvılcımı söndürmeyeceğim.', true, 'Aşk', 'Aşk', 2845, 859, 'approved', now() - interval '17087 minutes'),
  ('fa43e4a6-d757-445e-91c8-a39a78002277', (select id from public.profiles order by random() limit 1), 'Eşimle yıllardır süren tutkumuzun sırrı, yatak odamızı asla rutinin esiri etmememiz. Geçen hafta, ona sürpriz olarak, ortak bir hayalimizi gerçekleştirdik; bir gece için tüm telefonları kapattık, evi sadece mum ışığıyla aydınlattık ve birbirimize en sevdiğimiz anıları, en gizli arzularımızı fısıldadık. O karanlıkta, sadece birbirimizin sesini ve nefesini duyarak, yıllardır evli olduğumuz hâlde yeniden tanıştık sanki. O gece, aramızdaki bağın ne kadar derin olduğunu bir kez daha anladık. İtirafım: tutku, dış uyaranları kapatıp sadece birbirine odaklanınca daha da güçleniyormuş. O mum ışığı gecesi, evliliğimizin en sıcak anılarından biri oldu ve artık ayda bir bu ritüeli tekrarlıyoruz; herkese öneririm.', true, 'Fantezi', 'Fantezi', 1235, 104, 'approved', now() - interval '35573 minutes'),
  ('8c3d62a0-0092-422f-84e4-6fdfa7ef8a9f', (select id from public.profiles order by random() limit 1), 'Uçakta, yan koltuğumda oturan biriyle, türbülansta korkudan elini tuttuğum o an başlayan tanışıklık, koca bir yolculuğa dönüştü. Saatler süren uçuş boyunca hiç susmadan konuştuk, güldük, hayat hikâyelerimizi paylaştık ve indiğimizde sanki yıllardır tanışıyormuşuz gibi hissettik. Bavullarımızı beklerken bana seni bir daha görmek isterim dedi ve numaramı verirken elim titriyordu. O bulutların üstünde başlayan yakınlık, yerde de devam etti; şimdi her gün konuşuyoruz, ilk fırsatta buluşacağız. Bekarım ve yıllardır biri içimde bu kadar heyecan uyandırmamıştı. Bazen aşk, on bin metre yükseklikte, bir türbülans anında, tutulan bir elde başlıyormuş. O yolculuğu asla unutmayacağım, kaderin cilvesine inanmaya başladım.', true, 'Aşk', 'Aşk', 1560, 92, 'approved', now() - interval '24199 minutes'),
  ('07272967-7cf0-4c53-bd60-63e3cf814555', (select id from public.profiles order by random() limit 1), 'Eşim çok ölçülü, çok ciddi bir insan olduğu için aramızdaki tutkunun zamanla solmasından korkardım. Geçen ay, doğum gününde, onu yıllardır görmediğim bir şekilde şaşırtmaya karar verdim; evi onun en sevdiği çiçeklerle donattım, en güzel hâlimle hazırlandım ve kapıda muzip bir gülümsemeyle karşıladım. İçeri girdiğinde durakladı, gözlerindeki o ışıltı bana her şeyi anlattı. O gece, o ciddi maskenin altında saklı duran tutkulu, oyunbaz adamı tanıdım. Meğer içinde yıllardır beklediği bir ateş varmış. İtirafım: insanları olduğunu sandığınız kalıba hapsetmeyin, çünkü en sakin görünen eşinizin içinde sizi büyüleyecek bir alev olabilir. O gece evliliğimize yeniden tutku kattı.', true, 'Fantezi', 'Fantezi', 1015, 141, 'approved', now() - interval '15766 minutes'),
  ('b2e4b157-00fa-429a-8c7d-8cf9ff3f02b1', (select id from public.profiles order by random() limit 1), 'Mahallenin kahvesinde, her sabah aynı saatte gelen biriyle, bir gün masalar dolu olduğu için aynı masayı paylaşmak zorunda kaldık ve o tesadüf hayatımı değiştirdi. Kahvelerimizi içerken başlayan sohbet, o kadar akıcı, o kadar keyifliydi ki ikimiz de işe geç kaldık ama umursamadık. Gözlerindeki o zekâ, gülüşündeki o içtenlik beni anında etkiledi. Ertesi sabah ikimiz de yine o masada buluştuk, sonra bir alışkanlık oldu ve şimdi her sabahımız birbirimizle başlıyor. Bana dün gece seni düşündüm dediğinde kalbim yerinden fırladı. Bekarım ve yıllardır bu kadar mutlu olmamıştım. Bazen aşk, bir fincan kahvenin başında, paylaşılan bir masada filizleniyormuş. Her sabahı iple çekiyorum.', true, 'Aşk', 'Aşk', 864, 282, 'approved', now() - interval '20078 minutes'),
  ('d1a73c65-3e68-4d49-829e-f02e08deea15', (select id from public.profiles order by random() limit 1), 'Eşimle uzun yıllardır birlikteyiz ve tutkumuzu canlı tutmanın en güzel yolu, her zaman birbirimizi merak etmeye devam etmek oldu. Geçen hafta, eşim bana bir oyun önerdi; bir akşam için birbirimize hiç sormadığımız, en derin soruları sorduk ve cevapları dinledikçe, yıllardır birlikte olduğumuz hâlde birbirimiz hakkında bilmediğimiz ne çok şey olduğunu fark ettik. O sohbet, beklenmedik bir yakınlığa, sonra tutkulu bir geceye dönüştü. Meğer birini tamamen tanımak diye bir şey yokmuş, keşfedilecek hep yeni bir yan varmış. İtirafım: evliliği canlı tutan şey, birbirini sürekli yeniden keşfetme merakıymış. O soru oyunu, aramızdaki bağı daha da derinleştirdi ve evliliğimize yeni bir heyecan getirdi.', true, 'Fantezi', 'Fantezi', 1335, 132, 'approved', now() - interval '27929 minutes'),
  ('f9eef6b1-8126-46fc-b71c-236e64633354', (select id from public.profiles order by random() limit 1), 'Dans kursuna yalnız gittiğim ilk gün, eşleştirildiğim partnerimle aramızda öyle bir uyum, öyle bir elektrik oluştu ki müzik bittiğinde ikimiz de bırakmak istemedik. Her hareketinde bana öyle bir bakıyordu ki, dansın ritmiyle birlikte kalbim de hızlanıyordu. Birbirimize yaklaştığımız her figürde nefesim kesiliyor, yüzüm kızarıyordu. Ders bitince bir şeyler içmeye ne dersin dedi ve ben hevesle kabul ettim. O akşam dans pistinin dışında da aramızdaki o uyum devam etti; saatlerce konuştuk, güldük. Bekarım ve yıllardır biri içimde bu kadar heyecan uyandırmamıştı. Şimdi her dans dersini, onu göreceğim diye iple çekiyorum. Bazen aşk, bir dansın ritminde, birbirine değen ellerde doğuyormuş.', true, 'Aşk', 'Aşk', 1185, 139, 'approved', now() - interval '28672 minutes'),
  ('edd7d069-cdb0-431e-a937-6e374f72b2ad', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin en güzel yanı, birbirimize sürpriz yapmaktan hiç vazgeçmememiz. Geçen hafta, ben işten döndüğümde, eşim evi bambaşka bir atmosfere bürümüştü; loş ışıklar, yumuşak müzik, masada iki kadeh ve gözlerinde o yıllardır görmediğim muzip ışık. Bana bu akşam sadece ikimiz, hiçbir şey düşünme dedi ve elimden tutup beni o atmosferin içine çekti. O gece, yıllardır evli olduğumuz hâlde, yeniden âşık olduk; her dokunuş, her bakış ilk günkü gibi heyecan doluydu. İtirafım: tutku özel günleri beklemez, onu sıradan bir günde, küçük bir çabayla yeniden alevlendirmek mümkün. O akşam, evliliğimizin yorgun rutinini bir aşk gecesine çevirdi ve aramızdaki ateşi yeniden yaktı.', true, 'Fantezi', 'Fantezi', 1387, 113, 'approved', now() - interval '3685 minutes'),
  ('63d0b4f1-b867-44b1-8fe2-90ad8ad3377d', (select id from public.profiles order by random() limit 1), 'Tatil köyünde, akşam yemeğinde aynı masaya denk geldiğim biriyle, gece boyunca süren sohbet, beklenmedik bir tutkuya dönüştü. Aramızdaki o çekim o kadar yoğundu ki, başkalarının varlığını bile unuttuk, sadece birbirimize odaklandık. Yemekten sonra sahilde yürüdük, ay ışığının altında, dalga sesleri eşliğinde uzun uzun konuştuk, birbirimize sokulduk ve o an dünyada sadece ikimiz varmışız gibi hissettim. Tatil bitti ama biz ayrılmak istemedik; numaralarımızı paylaştık, şimdi her gün konuşuyoruz. Bekarız ikimiz de ve bu tatil aşkını gerçeğe dönüştürmeye kararlıyız. Bazen aşk, bir tatilin son gecesinde, ay ışığının altında, hiç tanımadığın birinin yanında alevleniyormuş. O geceyi asla unutmayacağım.', true, 'Aşk', 'Aşk', 1459, 178, 'approved', now() - interval '29908 minutes'),
  ('6c8a1a21-8356-41b2-a30d-d7d7892fb7ae', (select id from public.profiles order by random() limit 1), 'Eşimle yıllardır içimizde sakladığımız hayalleri bir gece cesaretle konuşmaya karar verdik ve bu, evliliğimizin dönüm noktası oldu. İkimiz de utana sıkıla en gizli arzularımızı anlattık ve meğer yıllardır birbirimizden sakladığımız o hayaller, şaşırtıcı derecede uyumluymuş. O gece, o paylaşımın getirdiği yakınlıkla, yıllardır hissetmediğimiz bir tutkuyla birbirimize sarıldık. Meğer aramızdaki mesafe, konuşmadığımız o konulardan kaynaklanıyormuş. İtirafım: çiftler birbirinden hayallerini, arzularını saklamasın; o suskunluk aranızdaki en güzel anları çalıyor ve sizi yabancılaştırıyor. O dürüst gece, evliliğimize yeni bir tutku, yeni bir yakınlık getirdi ve artık birbirimize her şeyi çekinmeden anlatabiliyoruz. Konuşmak her şeyi değiştirdi.', true, 'Fantezi', 'Fantezi', 69, 3, 'approved', now() - interval '17417 minutes'),
  ('29c02f63-28c3-441f-90f2-4f8b533ffb5a', (select id from public.profiles order by random() limit 1), 'İş yerindeki yeni stajyer, gülüşü ve enerjisiyle tüm ofise neşe getirdi ama en çok beni etkiledi. Ona bir şey öğretirken yanına eğildiğimde parfümünün kokusu burnuma doldu ve bir an ne söyleyeceğimi unuttum, kalbim hızlandı. O da bana öyle bir bakıyordu ki, aramızdaki gerilim her geçen gün artıyordu. Geçen gün ofiste geç saatte yalnız kaldık ve o an havadaki elektrik tavan yaptı; gözlerimiz kilitlendi, ikimiz de bir adım atmaktan korktuk ama o yakınlık nefesimizi kesti. İkimiz de bekarız ama iş yeri ilişkisi olur mu diye çekiniyorum. Her sabah onu görmek için işe bir heyecanla gidiyorum. Bu tatlı gerilimi daha ne kadar taşırım bilmiyorum; içimdeki bu yangın büyüyor.', true, 'Aşk', 'Aşk', 11144, 3187, 'approved', now() - interval '21292 minutes'),
  ('069e58a4-d0f8-452f-99b1-b91e61dd02a3', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin onuncu yılında, ilk balayımıza gittiğimiz şehre yeniden gitmeye karar verdik ve bu, beklediğimizden çok daha sihirli oldu. Aynı otele yerleştik, aynı sokaklarda el ele yürüdük ve on yıl önceki o genç, tutkulu âşıklara yeniden dönüştük. O ilk balayımızdaki heyecanı, merakı, tutkuyu yeniden yaşadık; sanki zaman geri sarmıştı. Akşam balkonda, şehrin ışıklarını izlerken eşim beni belimden tuttu ve seninle on yıl daha, sonra bir on yıl daha istiyorum dedi. O an gözlerim doldu. İtirafım: tutkuyu canlı tutmak için bazen geçmişin o güzel anılarına geri dönmek, onları yeniden yaşamak yetiyormuş. O yolculuk, evliliğimize ikinci bir balayı, yeni bir tutku getirdi.', true, 'Fantezi', 'Fantezi', 418, 286, 'approved', now() - interval '26933 minutes'),
  ('dc1c2e18-cab4-4b60-ad99-bc46710740a6', (select id from public.profiles order by random() limit 1), 'Komşumun bahçe partisinde, mangalın başında yardım ederken tanıştığım biriyle, akşam boyunca süren sohbet, beklenmedik bir yakınlığa dönüştü. Espri anlayışımız, hayata bakışımız o kadar uyumluydu ki saatlerin nasıl geçtiğini anlamadık. Bahçenin bir köşesinde, yıldızların altında yan yana oturduk ve omzu omzuma değdiğinde içimden tatlı bir ürperti geçti, kalbim hızlandı. Parti biterken bana numaranı alabilir miyim dedi ve ben kıpkırmızı vererek karşılık verdim. O geceden beri her gün mesajlaşıyoruz ve içimdeki o parti akşamının heyecanı hiç dinmedi. Bekarım ve yıllardır biri beni bu kadar etkilememişti. Bazen aşk, bir mangal partisinin dumanı arasında, hiç ummadığın bir köşede başlıyormuş.', true, 'Aşk', 'Aşk', 52000, 2607, 'approved', now() - interval '14307 minutes'),
  ('8c57535b-bf65-444f-be93-4d3528938361', (select id from public.profiles order by random() limit 1), 'Eşimle yatak odamızdaki tutkuyu canlı tutmanın bir yolunu bulduk; her ay birbirimize, asla tahmin edemeyeceğimiz bir tema sürprizi hazırlıyoruz. Bu ay sıra eşimdeydi ve eve geldiğimde beni bir not karşıladı; notu takip ettikçe bir gül, bir mum, bir mesaj... Sonunda yatak odasında, en romantik hâliyle beni bekliyordu. O kadar şaşırdım ki nefesim kesildi, yıllardır onu bu kadar tutkulu görmemiştim. O gece, sanki gizemli bir yabancıyla buluşuyordum; her an heyecan, her an keşif doluydu. İtirafım: evliliği bir maceraya çevirmek tamamen bizim elimizde ve biz bu macerayı her ay yeniden yazıyoruz. O sürpriz oyunları, aramızdaki ateşi hiç söndürmedi; tutku cesaretle besleniyormuş, herkese öneririm.', true, 'Fantezi', 'Fantezi', 1220, 555, 'approved', now() - interval '925 minutes'),
  ('2861dd45-369d-4be4-b576-02b99451f6fa', (select id from public.profiles order by random() limit 1), 'Üniversite kütüphanesinde, sınav haftası, aynı masayı paylaştığım biriyle, yorgunluktan göz göze geldiğimiz o an başlayan tanışıklık, sınavlardan çok daha unutulmaz oldu. Sessizlik kuralı yüzünden notlarla mesajlaştık, kâğıt parçalarına espriler yazdık ve aramızda tatlı bir oyun, tatlı bir yakınlık başladı. Kütüphane kapanınca dışarıda devam ettik; gece boyunca konuştuk, güldük, birbirimize sokulduk. Bana sınavlar bitince seninle gerçek bir randevuya çıkmak istiyorum dedi ve ben mutlulukla kabul ettim. Bekarım ve yıllardır biri içimde bu heyecanı uyandırmamıştı. Bazen aşk, sınav stresinin ortasında, paylaşılan kâğıt notlarında filizleniyormuş. O kütüphane gecelerini ve o tatlı oyunu asla unutmayacağım.', true, 'Aşk', 'Aşk', 1221, 118, 'approved', now() - interval '11589 minutes'),
  ('78d6657a-8795-4656-bf3c-cf5835c3a3d9', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu korumak için bir geleneğimiz var; her yıldönümünde, birbirimize o yıl yaşadığımız en güzel anı bir mektupla anlatıyoruz ve bu mektupları okumak hep beklenmedik bir yakınlığa dönüşüyor. Bu yıl eşimin mektubunu okurken gözlerim doldu; benim fark etmediğim, küçük anları o ne kadar değerli görmüş, ne kadar içten yazmış. O mektubu okuduktan sonra, o akşam birbirimize yeniden âşık olduk; sanki ilk günkü gibi. Meğer sevgiyi canlı tutan şey, küçük anların kıymetini bilmek ve bunu birbirine söyleyebilmekmiş. İtirafım: bizim bu mektup geleneğimiz, evliliğimizin en değerli hazinesi oldu. O mektuplar bir kutuda saklı ve her okuduğumuzda aramızdaki ateş yeniden tutuşuyor; tutku, dile getirilen sevgiyle besleniyormuş.', true, 'Fantezi', 'Fantezi', 536, 141, 'approved', now() - interval '7383 minutes'),
  ('90754275-bc45-4664-a4d6-607e5c0b11d9', (select id from public.profiles order by random() limit 1), 'Bir kafede, kitap okurken, aynı kitabı okuyan birinin masama yaklaşıp o kitabın sonunu sakın merak etme, muhteşem demesiyle başlayan tanışıklık, hayatımın en güzel sürprizi oldu. O kitap üzerine başlayan sohbet saatlerce sürdü, ortak zevklerimiz, hayallerimiz o kadar örtüşüyordu ki şaşırdık. Gözlerindeki o tutku, konuşmasındaki o derinlik beni büyüledi ve aramızda anında bir bağ kuruldu. Ayrılırken numaralarımızı paylaştık, şimdi her gün o kitabı, sonra hayatı konuşuyoruz. Bekarım ve yıllardır kalbim bu kadar hızlı atmamıştı. Bazen aşk, paylaşılan bir kitabın sayfaları arasında, bir yabancının samimi bir cümlesiyle başlıyormuş. O kafeyi, o anı ve o kitabı asla unutmayacağım; kaderin cilvesine inanmaya başladım.', true, 'Aşk', 'Aşk', 391, 127, 'approved', now() - interval '3026 minutes'),
  ('4de38c0e-076a-4c4c-8184-d57138b1a645', (select id from public.profiles order by random() limit 1), 'Eşimle uzun yıllardır birlikteyiz ve tutkumuzun hiç sönmemesinin sırrı, birbirimize her gün yeniden kur yapmaya devam etmemiz. Geçen hafta, sıradan bir akşam, eşim bana sanki yeni tanışıyormuşuz gibi yaklaştı, iltifatlar etti, elimi tuttu ve o eski flört oyununu yeniden başlattı. O akşam, yıllardır evli olduğumuz hâlde, ilk günkü gibi heyecanlandık, kıkırdadık, birbirimizi yeniden keşfettik. Meğer evliliği canlı tutan şey, kur yapmayı, flört etmeyi asla bırakmamakmış. İtirafım: eşinizi fethettiniz diye flörtü bırakmayın, çünkü asıl macera evlendikten sonra başlıyor. Bizim bu her gün yeniden kur yapma alışkanlığımız, evliliğimizi bir aşk hikâyesi gibi taze tutuyor ve aramızdaki ateş yıllar geçse de hiç sönmüyor.', true, 'Fantezi', 'Fantezi', 3646, 680, 'approved', now() - interval '4648 minutes'),
  ('74b02ab4-1928-45ae-9b5c-a50debd13f1b', (select id from public.profiles order by random() limit 1), 'Yağmurlu bir akşam, bir kafede sığındığım masada, karşıma oturan biriyle göz göze geldim ve o ıslak camlara vuran yağmurun ritmi eşliğinde başlayan sohbet, beklenmedik bir tutkuya dönüştü. Sıcacık kahvelerimizi içerken, dışarıdaki fırtınaya rağmen içimiz ısındı; her kelimesinde içim ürperdi, her gülüşünde kalbim hızlandı. Yağmur dinene kadar konuştuk, sonra dinince bile gitmek istemedik. Bana seni bir daha görmezsem çok pişman olurum dedi ve numaralarımızı paylaştık. O geceden beri her yağmurda o anı hatırlıyor, gülümsüyorum. Bekarım ve yıllardır biri beni bu kadar etkilememişti. Bazen aşk, bir yağmurun altında, sıcak bir kafede, bir fincan kahvenin başında başlıyormuş. O fırtınalı akşamı kalbimde saklıyorum.', true, 'Aşk', 'Aşk', 2974, 414, 'approved', now() - interval '9899 minutes'),
  ('4248555c-f387-4e63-9c0b-8abc0a57a34a', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu canlı tutmak için, ara sıra birbirimizi bambaşka mekânlarda, bambaşka kimliklerle buluşmaya davet ediyoruz. Geçen ay eşim bana, sanki internetten tanışan iki yabancıymışız gibi, bir kafede buluşma teklif etti. O gün ikimiz de o role öyle girdik ki, yıllardır evli olduğumuzu unutup, sıfırdan birbirimize âşık olduk; her bakış, her gülüş ilk randevu heyecanıyla doluydu. O oyun, aramızdaki o ilk günkü kıvılcımı yeniden tutuşturdu. İtirafım: evliliği canlı tutmanın en eğlenceli yolu, ara sıra birbirinize yabancı olup yeniden tanışmakmış. Bizim bu rol oyunlarımız, evliliğimizi bir maceraya çevirdi ve yıllar geçse de birbirimize her seferinde yeniden âşık oluyoruz; en sevdiğimiz oyunumuz bu oldu.', true, 'Fantezi', 'Fantezi', 588, 242, 'approved', now() - interval '5104 minutes'),
  ('5e502e1c-d7a9-4d4e-ba1e-99b3f6b1b5ce', (select id from public.profiles order by random() limit 1), 'Konser sonrası kalabalıkta, çıkışta sıkışınca yan yana düştüğüm biriyle, müziğin coşkusuyla başlayan sohbet, gecenin en güzel sürprizi oldu. İkimiz de aynı grubun hayranıydık ve o şarkıları konuşurken aramızda anında bir bağ, bir uyum kuruldu. Kalabalıktan çıkıp bir kenara çekildik, gece boyunca müziği, hayatı, hayalleri konuştuk ve birbirimize her geçen dakika daha çok yaklaştık. Gözlerindeki o ışık, gülüşündeki o enerji beni büyüledi. Ayrılırken numaralarımızı paylaştık ve şimdi birlikte konserlere gitme planları yapıyoruz. Bekarım ve yıllardır bu kadar heyecanlı hissetmemiştim. Bazen aşk, sevdiğin bir şarkının yankısında, bir konser çıkışının kalabalığında başlıyormuş. O geceyi ve o müziği asla unutmayacağım.', true, 'Aşk', 'Aşk', 489, 34, 'approved', now() - interval '4861 minutes'),
  ('ff48c5a1-6e53-489a-a6be-592aca9cd01d', (select id from public.profiles order by random() limit 1), 'Eşimle aramızdaki tutkuyu besleyen en güzel şey, asla birbirimizi yeterince tanıdığımızı düşünmememiz. Geçen hafta bir gece, ışıkları kısıp, sadece ikimiz, birbirimize hiç anlatmadığımız çocukluk hayallerimizi, en derin korkularımızı ve en gizli arzularımızı paylaştık. O gece, yıllardır birlikte olduğumuz hâlde birbirimizin yeni yönlerini keşfettik ve bu yakınlık, tutkulu bir geceye dönüştü. Meğer birini sevmek, onu sürekli yeniden keşfetmekmiş. İtirafım: evliliği canlı tutan şey, birbirinin iç dünyasına olan o bitmeyen merakmış. O gece, aramızdaki bağı daha da derinleştirdi ve evliliğimize yeni bir tutku, yeni bir yakınlık getirdi. Çiftlere tavsiyem; birbirinizi tanıdığınızı asla düşünmeyin, hep yeni bir kapı aralayın.', true, 'Fantezi', 'Fantezi', 7849, 3151, 'approved', now() - interval '20547 minutes'),
  ('a138e2ec-693f-49cc-9efd-fddeac57f294', (select id from public.profiles order by random() limit 1), 'Köpeğimi gezdirirken, parkta onun köpeğiyle benim köpeğim arkadaş olunca tanıştığım biriyle, hayvanlarımız oynaşırken başlayan sohbet, beklenmedik bir aşka dönüştü. Her sabah aynı saatte parkta buluşur olduk, köpeklerimiz koşarken biz banklarda saatlerce konuştuk, güldük ve aramızda tatlı bir yakınlık büyüdü. Gözlerindeki o şefkat, hayvanına olan sevgisi beni daha da etkiledi. Geçen gün elim eline değdi ve ikimiz de bir an durduk, gözlerimiz kilitlendi, kalbim hızlandı. Bana kahve içmeye ne dersin dedi ve ben hevesle kabul ettim. Bekarım ve yıllardır biri içimde bu heyecanı uyandırmamıştı. Bazen aşk, bir parkın yeşilinde, oynaşan iki köpeğin peşinde başlıyormuş. Her sabah o parkı iple çekiyorum.', true, 'Aşk', 'Aşk', 1448, 176, 'approved', now() - interval '16131 minutes'),
  ('da85aeb0-faf1-4a5f-9f9b-08216c688113', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin en güzel keşfi, tutkuyu beslemek için büyük jestlere gerek olmadığını anlamak oldu. Geçen hafta, sıradan bir akşam, eşim bana sadece bir bakışla, bir dokunuşla yıllardır hissetmediğim bir heyecan yaşattı. Mutfakta bulaşık yıkarken arkamdan sarıldı, kulağıma seni hâlâ ilk günkü gibi seviyorum diye fısıldadı ve o an dünyam durdu. O sıradan akşam, bir aşk gecesine dönüştü. Meğer tutku büyük sürprizlerde değil, küçük, içten anlarda saklıymış. İtirafım: eşinize bir bakış, bir dokunuş, bir fısıltı bazen en pahalı hediyeden daha değerli oluyor. O akşam, evliliğimizin rutininde saklı duran o ateşi yeniden hatırlattı bana. Küçük anların gücünü asla küçümsemeyin; tutku oralarda gizli.', true, 'Fantezi', 'Fantezi', 4649, 1917, 'approved', now() - interval '33545 minutes'),
  ('238de72e-e24d-431f-bf63-7e4cc3ef271b', (select id from public.profiles order by random() limit 1), 'Bir arkadaşımın doğum günü partisinde, hiç tanımadığım biriyle aynı köşede sıkışıp kalınca başlayan sohbet, gecenin en güzel anısı oldu. Müziğin gürültüsünde birbirimize doğru eğilip konuşmak zorunda kaldık ve o yakınlık, o fısıltılı sohbet aramızda tatlı bir gerilim yarattı. Gözlerindeki o ışık, gülüşündeki o sıcaklık beni anında etkiledi ve saatler boyunca sadece birbirimizle konuştuk. Parti biterken bana seni eve bırakabilir miyim dedi ve o yürüyüşte, gece sokaklarında, aramızdaki bağ daha da güçlendi. Numaralarımızı paylaştık ve şimdi her gün konuşuyoruz. Bekarım ve yıllardır bu kadar heyecanlı hissetmemiştim. Bazen aşk, bir partinin kalabalık köşesinde, fısıltıyla başlıyormuş. O geceyi asla unutmayacağım.', true, 'Aşk', 'Aşk', 343, 186, 'approved', now() - interval '35416 minutes'),
  ('e5826d21-995b-4e98-a41a-9d3a84e9a4eb', (select id from public.profiles order by random() limit 1), 'Eşimle yıllardır süren evliliğimizde, tutkuyu canlı tutmanın en güzel yolu birlikte yeni şeyler denemek oldu. Geçen ay, hiç gitmediğimiz bir dans kursuna yazıldık ve birbirimizin ellerini tutup, gözlerine bakarak dans etmeyi öğrenmek, aramızdaki o eski kıvılcımı yeniden tutuşturdu. Her figürde birbirimize yaklaştıkça, yıllardır kaybettiğimiz o heyecan geri geldi; eşimin dokunuşunda, bakışında yeniden o ilk günkü tutkuyu hissettim. Dersten sonra eve gülerek, el ele döndük, gencecik âşıklar gibiydik. İtirafım: evliliği canlı tutmak için birlikte yeni bir tutku, yeni bir uğraş edinmek harika işliyormuş. O dans kursu, aramızdaki bağı hem fiziksel hem ruhsal olarak güçlendirdi ve evliliğimize yeni bir heyecan kattı; herkese birlikte bir şeyler öğrenmeyi öneririm.', true, 'Fantezi', 'Fantezi', 3091, 1292, 'approved', now() - interval '26857 minutes'),
  ('a0915eda-aa69-4222-add1-f4a9c7fd48a4', (select id from public.profiles order by random() limit 1), 'Sahilde gün batımını izlerken, yanıma oturan biriyle, o muhteşem manzara karşısında başlayan sohbet, beklenmedik bir tutkuya dönüştü. İkimiz de o anın güzelliğine kapılmıştık ve birbirimize döndüğümüzde, gözlerimizde aynı hayranlığı gördük. Gün batarken konuştuk, hava kararınca da gitmek istemedik; yıldızlar çıkana kadar o sahilde, yan yana, birbirimize sokularak oturduk. Aramızdaki o yakınlık, o huzur tarif edilemezdi. Ayrılırken bana bu akşamı seninle paylaşmak bir hediyeydi dedi ve numaralarımızı verdik. Bekarım ve yıllardır biri içimde bu duyguyu uyandırmamıştı. Bazen aşk, bir gün batımının kızıllığında, bir sahil kenarında, bir yabancının yanında başlıyormuş. O akşamı, o manzarayı ve o anı kalbimde saklıyorum.', true, 'Aşk', 'Aşk', 1955, 396, 'approved', now() - interval '22338 minutes'),
  ('0eaeda10-b66c-42f5-91d9-46992daf2cb7', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu canlı tutmak için, birbirimize asla sıkıcı gelmemenin yollarını arıyoruz. Geçen hafta eşim, beni şaşırtmak için, gençken birlikte sık gittiğimiz o eski mekâna rezervasyon yaptırmış ve beni oraya sürpriz bir akşam yemeğine götürdü. O mekânda, gençlik anılarımız canlandı; ilk öpüşmemizi, ilk dansımızı, ilk kavgamızı ve barışmamızı hatırladık. O gece, yıllar öncesine döndük ve birbirimize yeniden, ilk günkü tutkuyla âşık olduk. Meğer anılar, tutkuyu yeniden alevlendiren en güçlü kıvılcımmış. İtirafım: bazen tutkuyu yeniden bulmak için, aşkın başladığı o yere geri dönmek yetiyormuş. O akşam, evliliğimize yeniden gençlik heyecanı kattı ve o eski mekân, yeniden bizim özel yerimiz oldu.', true, 'Fantezi', 'Fantezi', 1928, 789, 'approved', now() - interval '18631 minutes'),
  ('97385963-b07e-4dde-8b18-199497af37e0', (select id from public.profiles order by random() limit 1), 'Trende, uzun bir yolculukta, karşı koltuğumda oturan biriyle, manzarayı izlerken başlayan sohbet, saatler süren bir yakınlığa dönüştü. Pencereden geçen manzaralar eşliğinde, hayatımızı, hayallerimizi, korkularımızı paylaştık ve sanki yıllardır tanışıyormuşuz gibi hissettik. Aramızdaki o uyum, o çekim her geçen istasyonda biraz daha arttı. İnme vaktim geldiğinde gitmek istemedim ve o da bana numaranı ver, bu sohbet burada bitmesin dedi. O trende başlayan tanışıklık, inişten sonra da devam etti; şimdi her gün konuşuyoruz, ilk fırsatta buluşacağız. Bekarım ve yıllardır biri beni bu kadar etkilememişti. Bazen aşk, bir tren yolculuğunda, geçip giden manzaraların eşliğinde başlıyormuş. O yolculuğu ve o tanışmayı asla unutmayacağım.', true, 'Aşk', 'Aşk', 224, 77, 'approved', now() - interval '35578 minutes'),
  ('2f45e284-daa1-4fd0-9139-4edb38ecd546', (select id from public.profiles order by random() limit 1), 'Eşimle aramızdaki tutkuyu besleyen en güzel şey, birbirimize gün boyunca küçük, çapkın mesajlar atmamız. Sabah işe giderken bir mesaj, öğlen bir hatırlatma, akşama doğru bir vaat... Bu küçük oyun, akşamı dört gözle beklememizi sağlıyor ve eve geldiğimizde, gün boyu biriken o heyecanla birbirimize koşuyoruz. Meğer tutku, sadece akşamları değil, gün boyu beslenen bir ateşmiş. Eşimin gün ortasında gelen seni düşünüyorum mesajı, koca bir günü aydınlatıyor. İtirafım: evliliği canlı tutmak için pahalı hediyeler değil, gün içinde atılan küçük, sıcak mesajlar yetiyormuş. Bizim bu mesaj oyunumuz, evimizi yeniden bir balayı evine çevirdi ve aramızdaki ateş hiç sönmüyor; çiftlere bu küçük alışkanlığı şiddetle öneririm.', true, 'Fantezi', 'Fantezi', 11822, 983, 'approved', now() - interval '22610 minutes'),
  ('c3206e4d-4483-4a85-ae6b-ddae90d6884d', (select id from public.profiles order by random() limit 1), 'Bir fotoğraf sergisinde, aynı kareye dakikalarca bakan biriyle, o fotoğraf üzerine başlayan sohbet, beklenmedik bir aşka dönüştü. Sanattan, hayattan, anlardan konuşurken gözlerindeki o derinlik beni büyüledi ve aramızda anında bir bağ kuruldu. Sergiyi birlikte gezdik, her karede fikir alışverişi yaptık ve dar bir koridorda yan yana geçerken omzumuz değdi, ikimiz de durduk, gözlerimiz kilitlendi, kalbim hızlandı. Bana bu sohbeti bir kahve eşliğinde sürdürelim mi dedi ve ben hevesle kabul ettim. Bekarım ve yıllardır biri zihnimi ve kalbimi bu kadar etkilememişti. Şimdi her sergiye birlikte gidiyoruz. Bazen aşk, bir fotoğraf karesinin önünde, paylaşılan bir bakışta doğuyormuş. O sergiyi ve o anı asla unutmayacağım.', true, 'Aşk', 'Aşk', 40, 37, 'approved', now() - interval '32693 minutes'),
  ('fe6eae03-4d14-4e1c-aa32-80e833ecddff', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu korumanın en güzel yolu, asla birbirimize hayır demeyi sevgisizlik sanmamak ama her zaman birbirimizin arzularına açık olmak oldu. Geçen hafta, eşim yıllardır içinde sakladığı bir hayalini bana açtı ve ben onu yargılamadan, sevgiyle dinledim. O gece, o paylaşımın getirdiği güvenle, yıllardır hissetmediğimiz bir tutkuyla birbirimize sarıldık. Meğer en büyük yakınlık, en gizli arzularını çekinmeden paylaşabildiğin, yargılanmayacağını bildiğin insanla oluyormuş. İtirafım: bir evlilikte güven, tutkunun en güçlü besinidir. O gece, eşimin bana duyduğu güveni, açıklığı görmek beni daha çok âşık etti. Çiftlere tavsiyem; birbirinizin hayallerini yargılamadan dinleyin, çünkü o güven aranızdaki ateşi hiç söndürmez.', true, 'Fantezi', 'Fantezi', 4548, 228, 'approved', now() - interval '29687 minutes'),
  ('ec386f39-e630-493d-a666-47ec8ffb2bb4', (select id from public.profiles order by random() limit 1), 'Bisiklet turunda, aynı molada dinlenirken tanıştığım biriyle, doğanın ortasında başlayan sohbet, beklenmedik bir tutkuya dönüştü. Ter içinde, nefes nefese ama mutlu, manzaranın güzelliğini paylaşırken aramızda anında bir uyum kuruldu. Turun geri kalanını yan yana pedal çevirerek, gülüşerek, yarışarak tamamladık ve her an birbirimize biraz daha yaklaştık. Tur bitince bana bu enerjiyi seninle paylaşmak harikaydı, devamı gelsin dedi ve numaralarımızı verdik. O günden beri her hafta sonu birlikte bisiklete biniyoruz, hem spor hem aşk. Bekarım ve yıllardır biri içimde bu heyecanı uyandırmamıştı. Bazen aşk, açık havada, bir bisiklet selesinde, paylaşılan bir terde başlıyormuş. O turu ve o tanışmayı asla unutmayacağım, hayata yeniden bağlandım.', true, 'Aşk', 'Aşk', 329, 131, 'approved', now() - interval '26279 minutes'),
  ('b7b0f30c-5e85-4591-b1fb-fb6184793252', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin en güzel sırrı, birbirimize her zaman yeni bir macera vaat etmemiz. Geçen ay, eşim bana bir gece için planladığı sürpriz bir tema akşamı düzenledi; evi bir başka şehrin atmosferine büründürmüş, o şehrin müziğini açmış, yemeklerini hazırlamış ve beni hayali bir yolculuğa çıkarmıştı. O gece, evimizden hiç çıkmadan bambaşka bir dünyaya yolculuk ettik ve bu macera, aramızdaki tutkuyu yeniden alevlendirdi. Meğer hayal gücü, en güçlü afrodizyakmış. İtirafım: evliliği canlı tutmak için pahalı tatillere gerek yok, biraz hayal gücü ve emek yetiyormuş. O tema gecesi, evliliğimize yeni bir heyecan, yeni bir keşif duygusu kattı ve artık her ay birbirimize böyle hayali yolculuklar düzenliyoruz; evimiz bir maceraya dönüştü.', true, 'Fantezi', 'Fantezi', 1388, 565, 'approved', now() - interval '5726 minutes'),
  ('e5650831-19c1-4e1e-bab9-f119b2a939e5', (select id from public.profiles order by random() limit 1), 'Müzik festivalinde, kalabalığın içinde kaybolduğumda yardımıma koşan biriyle, o curcunada başlayan tanışıklık, festivalin en güzel anısı oldu. Beni kalabalıktan çıkarıp bir kenara aldı ve o andan sonra festivali birlikte gezdik; aynı şarkılara dans ettik, aynı anlara güldük ve aramızda anında bir bağ kuruldu. Gece, sahnenin ışıkları altında, müziğin coşkusuyla birbirimize sokulduk ve o an dünyada sadece ikimiz varmışız gibi hissettim. Festival biterken numaralarımızı paylaştık ve şimdi birlikte konser planları yapıyoruz. Bekarım ve yıllardır bu kadar canlı, bu kadar mutlu hissetmemiştim. Bazen aşk, bir festivalin kaosunda, uzanan bir yardım elinde başlıyormuş. O festivali, o müziği ve o anı kalbimde sonsuza dek saklayacağım.', true, 'Aşk', 'Aşk', 2193, 215, 'approved', now() - interval '20529 minutes'),
  ('bb698d91-8b80-4932-9fc5-1cd60b600b6a', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu canlı tutmak için, birbirimize sürekli iltifat etmeyi, birbirimizi takdir etmeyi asla bırakmadık. Geçen hafta, sıradan bir akşam, eşim bana uzun uzun baktı ve seninle evlenmek hayatımın en güzel kararıydı dedi. O an, yıllardır evli olmamıza rağmen, kalbim ilk günkü gibi hızlandı ve gözlerim doldu. O içten sözler, o akşamı bir aşk gecesine çevirdi. Meğer tutku, sadece fiziksel değil, sözlerle, takdirle de besleniyormuş. İtirafım: eşinize ne kadar sevdiğinizi, ne kadar takdir ettiğinizi söylemeyi asla bırakmayın, çünkü o sözler aranızdaki ateşi diri tutuyor. Bizim birbirimize hiç eksik etmediğimiz o iltifatlar, evliliğimizi yıllar geçse de taze ve tutkulu tutuyor; sözün gücünü küçümsemeyin.', true, 'Fantezi', 'Fantezi', 5389, 2957, 'approved', now() - interval '31186 minutes'),
  ('0c8e1cc7-1b3b-414c-a721-6b6a1948b051', (select id from public.profiles order by random() limit 1), 'Bir hayır etkinliğinde gönüllü olarak çalışırken, aynı masada görev aldığım biriyle, iyilik yaparken başlayan tanışıklık, beklenmedik bir aşka dönüştü. İnsanlara yardım ederken, onun o şefkatli kalbini, o güzel gülüşünü görmek beni anında etkiledi. Mola verdiğimizde sohbet ettik ve hayata bakışımızın, değerlerimizin ne kadar örtüştüğünü fark ettik. Gözlerindeki o iyilik, o samimiyet beni büyüledi. Etkinlik bitince bana bu enerjiyi seninle paylaşmak güzeldi, bir kahve içelim mi dedi ve ben mutlulukla kabul ettim. Bekarım ve yıllardır biri içimde bu duyguyu uyandırmamıştı. Bazen aşk, iyilik yaparken, başkalarına uzanan ellerin arasında filizleniyormuş. O etkinliği ve o tanışmayı asla unutmayacağım; iyilik bana aşkı getirdi.', true, 'Aşk', 'Aşk', 1214, 47, 'approved', now() - interval '21892 minutes'),
  ('6310dfcf-173d-49ac-bec8-a9cd5dc0ead9', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizde tutkuyu canlı tutan en güzel şey, birbirimize hâlâ utanabilmemiz, hâlâ heyecanlanabilmemiz. Geçen hafta, eşim bana yıllar önce ilk buluşmamızda giydiğim parfümü hatırlatınca, o parfümü tekrar aldım ve bir akşam sürpriz olarak süründüm. Eve geldiğinde o kokuyu alınca durakladı, gözlerinde o ilk günkü ışık belirdi ve beni o anıların içine, o ilk buluşmamıza götürdü. O gece, yıllar öncesine döndük, ilk günkü gibi heyecanlandık. Meğer bir koku bile, tüm o eski tutkuyu geri getirebiliyormuş. İtirafım: anıları canlandıran küçük detaylar, tutkuyu yeniden alevlendiren en güçlü araçlarmış. O parfüm gecesi, evliliğimize yeniden o ilk günkü heyecanı kattı ve artık o koku, bizim özel sırrımız oldu; küçük detayların gücünü keşfettik.', true, 'Fantezi', 'Fantezi', 661, 82, 'approved', now() - interval '21487 minutes'),
  ('054a5d13-34e3-4fb5-95f0-ff46bd0ad24f', (select id from public.profiles order by random() limit 1), 'Akşam yürüyüşümde, parkta her gün karşılaştığım biriyle, başta sadece bir baş selamıyla başlayan tanışıklık, giderek uzayan sohbetlere ve sonunda bir aşka dönüştü. Her akşam aynı bankta buluşur olduk, gün içinde yaşadıklarımızı paylaştık, hayaller kurduk ve aramızda tatlı bir yakınlık büyüdü. Geçen akşam, hava serinleyince ceketini omzuma attı ve o an içimden tatlı bir sıcaklık geçti, kalbim hızlandı. Bana her akşam seni görmek günümün en güzel anı oldu dedi ve o an gözlerim doldu. Bekarım ve yıllardır biri içimde bu huzuru, bu heyecanı uyandırmamıştı. Bazen aşk, her akşam aynı bankta, paylaşılan sıradan anlarda usulca filizleniyormuş. O akşam yürüyüşlerini ve o bankı asla unutmayacağım; en güzel anılarım orada.', true, 'Aşk', 'Aşk', 1066, 328, 'approved', now() - interval '16589 minutes'),
  ('8904633d-e605-49fe-9a4c-bfe0334793f7', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu korumanın sırrı, birbirimize her zaman öncelik vermemiz. Ne kadar yorgun, ne kadar meşgul olursak olalım, her akşam en az yarım saatimizi sadece ikimize, hiçbir ekran olmadan ayırıyoruz. Bu yarım saatte bazen konuşuyoruz, bazen sarılıp müzik dinliyoruz, bazen sadece birbirimizin gözlerine bakıyoruz. Bu küçük ritüel, koca bir günün yorgunluğunu alıp götürüyor ve aramızdaki bağı her gün tazeliyor. Meğer tutkuyu canlı tutan şey, birbirine ayrılan o korunaklı, kesintisiz zamanmış. İtirafım: evliliği taze tutmak için günde yarım saat bile yetiyormuş, yeter ki o zaman gerçekten birbirinize ait olsun. Bizim bu her akşamki yarım saatimiz, evliliğimizin can damarı oldu ve aramızdaki ateş hiç sönmedi; bu alışkanlığı herkese öneririm.', true, 'Fantezi', 'Fantezi', 555, 77, 'approved', now() - interval '21397 minutes'),
  ('9e008125-fb7b-4ee2-9f8a-708ae73f49bf', (select id from public.profiles order by random() limit 1), 'Bir kokteyl partisinde, kimseyi tanımadığım için bir köşede duruyordum ki, yanıma yaklaşan biri bana sen de mi burada kimseyi tanımıyorsun deyince ikimiz de güldük ve o an buz eridi. O akşam, o kalabalık partide, birbirimizin tek tanıdığı olduk; bir köşede saatlerce konuştuk, güldük, başkalarını unuttuk. Gözlerindeki o muziplik, sohbetindeki o akıcılık beni anında etkiledi ve aramızda tatlı bir gerilim oluştu. Parti biterken bana bu akşam seni tanımak en güzel sürprizdi dedi ve numaralarımızı paylaştık. Bekarım ve yıllardır biri içimde bu heyecanı uyandırmamıştı. Bazen aşk, kimseyi tanımadığın bir partinin köşesinde, paylaşılan bir tebessümle başlıyormuş. O partiyi ve o tanışmayı asla unutmayacağım; en güzel anılar en beklenmedik anlarda.', true, 'Aşk', 'Aşk', 86, 43, 'approved', now() - interval '19261 minutes'),
  ('02628f02-e604-42aa-a1c8-0e43291f93f0', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu canlı tutmak için, ara sıra sıradanlığın dışına çıkıp birlikte küçük çılgınlıklar yapıyoruz. Geçen hafta, gece yarısı birden karar verip arabaya atladık, şehir dışına çıktık ve hiç ışık olmayan bir tepede, arabanın kaputuna uzanıp yıldızları izledik. O sessizlikte, o sonsuz gökyüzünün altında, birbirimize sarılıp hayaller kurduk, geçmişi andık, geleceği planladık. O gece, yıllardır hissetmediğimiz bir özgürlük, bir tutku yaşadık. Meğer evliliği canlı tutan şey, ara sıra yapılan o plansız, çılgın anlarmış. İtirafım: bazen en güzel anılar, hiç planlamadan, bir anda alınan kararlarla yaşanıyormuş. O yıldız izleme gecesi, evliliğimize yeni bir tutku, yeni bir özgürlük getirdi ve artık ara sıra böyle çılgınlıklar yapmaktan çekinmiyoruz.', true, 'Fantezi', 'Fantezi', 1519, 129, 'approved', now() - interval '28761 minutes'),
  ('b4fe75aa-eecc-46e3-b60b-5497dc8f69e1', (select id from public.profiles order by random() limit 1), 'Üniversitedeki bir konferansta, yanıma oturan biriyle, konuşmacının bir esprisine aynı anda gülünce başlayan tanışıklık, beklenmedik bir aşka dönüştü. Mola sırasında sohbet ettik ve fikirlerimizin, ilgi alanlarımızın ne kadar örtüştüğünü görünce ikimiz de şaşırdık. Konferans boyunca notlar paylaştık, fısıltıyla yorumlar yaptık ve aramızda tatlı bir yakınlık büyüdü. Konferans bitince bana bu sohbeti bir akşam yemeğinde sürdürelim mi dedi ve ben mutlulukla kabul ettim. O akşam saatlerce konuştuk ve aramızdaki bağ daha da güçlendi. Bekarım ve yıllardır biri zihnimi ve kalbimi aynı anda bu kadar etkilememişti. Bazen aşk, bir konferans salonunda, paylaşılan bir kahkahayla başlıyormuş. O günü asla unutmayacağım; en güzel başlangıçlar en sade anlarda.', true, 'Aşk', 'Aşk', 1171, 84, 'approved', now() - interval '25645 minutes'),
  ('ec37baa8-8dd5-42e2-8639-4e5d4698bd82', (select id from public.profiles order by random() limit 1), 'Eşimle evliliğimizin tutkusunu canlı tutmanın en güzel yolu, ara sıra birbirimize küçük ''randevu kuponları'' hediye etmemiz oldu. Her birimiz, diğerine bir kupon yazıyor; bir akşam dans, bir gece yıldız izleme, bir sürpriz yemek gibi ve diğeri istediği zaman o kuponu kullanıyor. Geçen hafta eşim bana yıllardır sakladığı bir kuponu uzattı ve o akşam, o kuponun vaat ettiği romantik geceyi birlikte yaşadık; mum ışığı, müzik, sadece ikimiz. O gece, yıllardır evli olduğumuz hâlde, gencecik âşıklar gibi heyecanlandık. Meğer evliliği canlı tutan şey, birbirine sürekli yeni anlar, yeni sürprizler vaat etmekmiş. İtirafım: bu küçük kupon oyunu, evliliğimizi bir sürpriz kutusuna çevirdi ve aramızdaki ateş hiç sönmedi; çiftlere bu eğlenceli oyunu şiddetle öneririm.', true, 'Fantezi', 'Fantezi', 589, 172, 'approved', now() - interval '35076 minutes');
